// Self-contained: it is serialised with toString() into the Blob worker, so it must
// not reference anything outside its own body. `self` is the worker global, or a
// small stand-in {postMessage, onmessage} when it runs on the page.
function assetLoaderMain(self) {
  'use strict';
  const OWN_CACHE = 'sro-asistan-assets-v1';
  const GAME_CACHE = 'sro-next-verified-v1';
  const GAME_PACK_MAX = 4 << 20; // the game caches whole packs up to this size
  const NET_SLOTS = 6;
  const OWN_CACHE_MAX = 6000; // entries; the oldest half is dropped above this
  let ORIGIN = '';
  let manifestP = null;
  let manifestAt = 0;
  let manifestGen = 0; // bumped on every successful manifest load
  let forcedAt = 0;
  let refreshing = null;
  let manifestInfo = null;
  const heads = new Map(); // packPath -> Promise<data start offset>
  const caches_ = new Map(); // name -> Promise<Cache|null>
  let skillRows = null;
  const stats = {
    requests: 0,
    ok: 0,
    fail: 0,
    ownCache: 0,
    gameCache: 0,
    gamePack: 0,
    transport: 0,
    range: 0,
    retries: 0,
    manifestLoads: 0,
    bytes: 0,
    lastError: '',
  };

  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  function fail(code, message, status) {
    const e = new Error(message);
    e.code = code;
    if (status) e.status = status;
    return e;
  }

  // ---- network ----------------------------------------------------------

  const slots = { n: 0, q: [] };
  async function withSlot(fn) {
    while (slots.n >= NET_SLOTS) await new Promise((r) => slots.q.push(r));
    slots.n++;
    try {
      return await fn();
    } finally {
      slots.n--;
      const next = slots.q.shift();
      if (next) next();
    }
  }

  async function fetchBytes(url, opt) {
    opt = opt || {};
    const ctl = new AbortController();
    const timer = setTimeout(() => ctl.abort(), opt.timeout || 30000);
    try {
      const init = { cache: opt.cache || 'no-cache', credentials: 'same-origin', signal: ctl.signal };
      if (opt.range) init.headers = { Range: 'bytes=' + opt.range[0] + '-' + opt.range[1] };
      const res = await fetch(ORIGIN + url, init);
      if (!(res.ok || res.status === 206)) throw fail('http', url + ' HTTP ' + res.status, res.status);
      let bytes = new Uint8Array(await res.arrayBuffer());
      if (opt.range) {
        if (res.status !== 206) bytes = bytes.subarray(opt.range[0], opt.range[1] + 1);
        if (bytes.length !== opt.range[1] - opt.range[0] + 1) throw fail('format', url + ': kısa yanıt (' + bytes.length + ' bayt)');
      }
      stats.bytes += bytes.length;
      return bytes;
    } catch (e) {
      if (e && e.code) throw e;
      if (ctl.signal.aborted) throw fail('timeout', 'zaman aşımı: ' + url);
      throw fail('network', 'ağ hatası: ' + url + ' (' + ((e && e.message) || e) + ')');
    } finally {
      clearTimeout(timer);
    }
  }

  async function gunzip(bytes) {
    if (typeof DecompressionStream !== 'function') throw fail('format', 'tarayıcı gzip açamıyor (DecompressionStream yok)');
    try {
      const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('gzip'));
      return new Uint8Array(await new Response(stream).arrayBuffer());
    } catch (e) {
      throw fail('format', 'gzip açılamadı: ' + ((e && e.message) || e));
    }
  }

  async function sha256(bytes) {
    const d = new Uint8Array(await crypto.subtle.digest('SHA-256', bytes));
    let s = '';
    for (const b of d) s += b.toString(16).padStart(2, '0');
    return s;
  }

  // ---- Cache Storage ----------------------------------------------------

  function openCache(name) {
    if (!caches_.has(name)) {
      caches_.set(
        name,
        Promise.resolve()
          .then(() => (typeof caches === 'undefined' ? null : name === GAME_CACHE ? caches.has(name).then((ok) => (ok ? caches.open(name) : null)) : caches.open(name)))
          .catch(() => null)
      );
    }
    return caches_.get(name);
  }

  async function cacheGet(name, key) {
    try {
      const c = await openCache(name);
      if (!c) return null;
      const r = await c.match(key);
      return r ? new Uint8Array(await r.arrayBuffer()) : null;
    } catch {
      return null;
    }
  }

  let ownPuts = 0;
  function putOwn(sha, bytes) {
    openCache(OWN_CACHE)
      .then((c) => c && c.put(ORIGIN + '/__sro_asistan__/' + sha, new Response(bytes, { headers: { 'content-type': 'application/octet-stream' } })))
      .catch(() => {});
    if (++ownPuts === 50) setTimeout(pruneOwn, 20000);
  }

  async function pruneOwn() {
    try {
      const c = await openCache(OWN_CACHE);
      if (!c) return;
      const keys = await c.keys();
      if (keys.length <= OWN_CACHE_MAX) return;
      for (const k of keys.slice(0, keys.length - OWN_CACHE_MAX / 2)) await c.delete(k);
    } catch {}
  }

  // ---- manifest ---------------------------------------------------------

  function manifest(force) {
    if (force || !manifestP) {
      const p = (async () => {
        let last = null;
        for (let i = 0; i < 3; i++) {
          try {
            const bytes = await fetchBytes('/assets/packs/manifest.json', { timeout: 90000 });
            let data;
            try {
              data = JSON.parse(new TextDecoder().decode(bytes));
            } catch {
              throw fail('format', 'manifest JSON okunamadı');
            }
            if (!data || !Array.isArray(data.assets)) throw fail('format', 'manifest biçimi tanınmadı (' + ((data && data.format) || '?') + ')');
            const assets = new Map();
            for (const a of data.assets) if (a && a.path && a.packPath) assets.set(String(a.path).toLowerCase(), a);
            const packs = new Map();
            for (const g of data.groups || []) for (const pk of (g && g.packs) || []) if (pk && pk.path) packs.set(pk.path, pk);
            stats.manifestLoads++;
            manifestGen++;
            manifestAt = Date.now();
            manifestInfo = {
              format: data.format || '',
              generatedAt: data.generatedAt || '',
              deliveryVersion: data.deliveryVersion == null ? '' : String(data.deliveryVersion),
              assets: assets.size,
              packs: packs.size,
            };
            return { assets, packs };
          } catch (e) {
            last = e;
            if (i < 2) await sleep(1500 * (i + 1));
          }
        }
        if (last) last.manifest = true;
        throw last;
      })();
      manifestP = p;
      p.catch(() => {
        if (manifestP === p) manifestP = null;
      });
    }
    return manifestP;
  }

  // Re-read the manifest after a sign that the packs were republished. Concurrent
  // failures share one download, and a forced re-read happens at most every 30 s.
  function refreshManifest(seenGen) {
    if (refreshing) return refreshing;
    if (manifestGen > seenGen || Date.now() - forcedAt < 30000) return manifest();
    forcedAt = Date.now();
    const p = manifest(true);
    refreshing = p;
    const done = () => {
      if (refreshing === p) refreshing = null;
    };
    p.then(done, done);
    return p;
  }

  function packStart(packPath) {
    if (!heads.has(packPath)) {
      const p = fetchBytes(packPath, { range: [0, 11], timeout: 30000 }).then((h) => {
        let magic = '';
        for (let i = 0; i < 8; i++) magic += String.fromCharCode(h[i]);
        if (magic !== 'SROPACK1') throw fail('format', 'paket kimliği hatalı: ' + packPath);
        const len = new DataView(h.buffer, h.byteOffset, h.byteLength).getUint32(8, true);
        if (len > 16 << 20) throw fail('format', 'paket başlığı hatalı: ' + packPath);
        return 12 + len;
      });
      p.catch(() => heads.delete(packPath));
      heads.set(packPath, p);
    }
    return heads.get(packPath);
  }

  // ---- one asset --------------------------------------------------------

  async function fromCaches(m, asset) {
    const own = await cacheGet(OWN_CACHE, ORIGIN + '/__sro_asistan__/' + asset.sha256);
    if (own && own.length === asset.length && (await sha256(own)) === asset.sha256) {
      stats.ownCache++;
      return own;
    }
    const game = await cacheGet(GAME_CACHE, ORIGIN + '/assets/.verified/' + asset.sha256);
    if (game && game.length === asset.length && (await sha256(game)) === asset.sha256) {
      stats.gameCache++;
      return game;
    }
    const pk = m.packs.get(asset.packPath);
    if (pk && pk.sha256 && pk.bytes <= GAME_PACK_MAX) {
      const pack = await cacheGet(GAME_CACHE, ORIGIN + '/assets/.verified/' + pk.sha256);
      if (pack && pack.length >= 12) {
        const len = new DataView(pack.buffer, pack.byteOffset, pack.byteLength).getUint32(8, true);
        const start = 12 + len + asset.offset;
        if (start + asset.length <= pack.length) {
          const b = pack.slice(start, start + asset.length);
          if ((await sha256(b)) === asset.sha256) {
            stats.gamePack++;
            return b;
          }
        }
      }
    }
    return null;
  }

  async function fromNetwork(asset) {
    if (asset.transport && asset.transport.path) {
      try {
        const gz = await fetchBytes(asset.transport.path, { timeout: 60000, cache: 'default' });
        if (asset.transport.sha256 && (await sha256(gz)) !== asset.transport.sha256) throw fail('checksum', 'taşıma dosyası SHA-256 tutmuyor: ' + asset.path);
        const raw = await gunzip(gz);
        stats.transport++;
        return raw;
      } catch (e) {
        // The transport copy is an optimisation; the pack still has the bytes.
        if (!asset.packPath) throw e;
      }
    }
    const start = (await packStart(asset.packPath)) + asset.offset;
    const raw = await fetchBytes(asset.packPath, { range: [start, start + asset.length - 1], timeout: 45000 });
    stats.range++;
    return raw;
  }

  // tries: {refreshed, waits}: one manifest re-read and up to 3 backoff waits per request.
  async function bytesOf(path, tries) {
    const t = tries || { refreshed: false, waits: 0 };
    if (!tries) stats.requests++;
    let retry = ''; // 'manifest': re-read the manifest first; 'wait': back off
    let error = null;
    let gen = manifestGen;
    try {
      const m = await manifest();
      gen = manifestGen;
      const key = String(path).toLowerCase();
      let asset = m.assets.get(key);
      let gz = false;
      if (!asset && key.endsWith('.json')) {
        asset = m.assets.get(key + '.gz');
        gz = !!asset;
      }
      if (asset) {
        let raw = await fromCaches(m, asset);
        if (!raw) {
          raw = await withSlot(() => fromNetwork(asset));
          if (raw.length !== asset.length) throw fail('format', 'uzunluk tutmuyor: ' + path);
          if ((await sha256(raw)) !== asset.sha256) throw fail('checksum', 'SHA-256 tutmuyor: ' + path);
          putOwn(asset.sha256, raw);
        }
        if (gz || /\.gz$/i.test(asset.path)) raw = await gunzip(raw);
        stats.ok++;
        return { bytes: raw, mime: asset.mime || '' };
      }
      // Possibly a file added by a later deploy: re-read an older manifest once.
      if (!t.refreshed && Date.now() - manifestAt > 120000) retry = 'manifest';
      else throw fail('missing', 'oyun paketlerinde yok: ' + path);
    } catch (e) {
      error = e;
      const code = e && e.code;
      const status = e && e.status;
      const stale = code === 'checksum' || code === 'format' || (code === 'http' && (status === 404 || status === 410 || status === 416));
      const transient = code === 'timeout' || code === 'network' || (code === 'http' && status >= 500) || !code;
      if (e && e.manifest) retry = ''; // the manifest download has its own retries
      else if (stale && !t.refreshed) retry = 'manifest';
      else if ((transient || stale) && t.waits < 3) retry = 'wait';
    }
    if (retry) {
      stats.retries++;
      if (retry === 'manifest') {
        t.refreshed = true;
        await refreshManifest(gen).catch(() => {});
      } else {
        await sleep(700 * 2 ** t.waits);
        t.waits++;
      }
      return bytesOf(path, t);
    }
    stats.fail++;
    stats.lastError = String((error && error.message) || error);
    throw error;
  }

  // ---- skillData.json ---------------------------------------------------

  // Parameter walker (tag -> arity), mirrors the client tooltip parser.
  const TAGS = {att:5,pdmg:1,pdm2:1,ko:2,da:1,cr:2,ck:1,gdr:1,hr:2,ru:1,kb:2,saps:2,defp:3,defr:3,ar:2,dar:2,odar:2,br:2,er:2,dura:1,onff:2,mc:2,efr:6,eshp:0,stns:3,esht:2,fitp:2,cnsm:3,rhru:2,dcmp:1,hpi:2,mpi:2,pw:4,hste:1,hst2:1,hst3:1,irgc:2,apru:2,apau:2,terd:1,thrd:1,tpdd:1,tpad:1,tele:2,tel2:2,tel3:2,reat:2,bgra:2,real:3,pola:2,summ:5,fz:2,fb:2,es:3,bu:3,ps:3,zb:2,heal:4,resu:2,cura:1,pmhp:4,pmmp:4,pmdp:4,pmdg:4,pao:1,cbuf:0,nbuf:0,bbuf:0,pcdu:1,chcr:1,cmcr:1,lnks:4,lks2:0,lkcp:1,ovl2:1,scls:1,puls:1,reqc:1,reqi:2,reqn:0,atca:2,tant:2,tnt2:2,dtnt:2,dmgt:2,dru:2,dru2:2,stri:2,spda:2,expi:2,inti:2,abir:1,tkss:1,lfst:1,tran:3,curt:2,curl:3,rcur:1,dmgr:4,dgmp:1,hwir:1,abnb:1,dtt:2,dttp:2,hide:3,dcri:1,se:3,rt:3,sl:3,fe:3,my:4,bl:5,dn:4,st:3,ds:4,ca:3,cssr:4,csit:4,cspd:4,csmd:4,cshp:6,csmp:6,tb:4,lkdr:3,lkag:2,lkdd:1,thld:1,tcmd:2,skc:3,pchr:1,qest:4,msch:2,mcap:2,rmut:1,alcu:1,luck:1,pwtt:1,mwtt:1,pwdt:1,mwdt:1,mwhh:1,mwmh:1,mwhs:1,mstc:1,mscc:1,lkdh:3,hitm:0,hntp:0,trap:0,efta:0,ao:0,rpkt:0,ssou:-1,getv:1,setv:3};
  const TAG = new Map();
  for (const [name, arity] of Object.entries(TAGS)) {
    let code = 0;
    for (const c of name) code = ((code << 8) | c.charCodeAt(0)) >>> 0;
    TAG.set(code, { name, arity });
  }

  function walk(values) {
    const out = {};
    for (let p = 0; p < values.length; ) {
      const v = values[p] >>> 0;
      if (v === 0) {
        p++;
        continue;
      }
      const t = TAG.get(v);
      if (!t || p + t.arity >= values.length) {
        p++;
        continue;
      }
      if (t.arity < 0) break;
      if (!(t.name in out)) out[t.name] = values.slice(p + 1, p + 1 + t.arity);
      p += 1 + t.arity;
    }
    return out;
  }

  function decodeJson(bytes) {
    try {
      return JSON.parse(new TextDecoder().decode(bytes));
    } catch {
      throw fail('format', 'JSON okunamadı');
    }
  }

  async function skillInfo(ids) {
    if (!skillRows) {
      const data = decodeJson((await bytesOf('/assets/data/skillData.json')).bytes);
      const rows = new Map();
      for (const row of data.rows || []) {
        const tab = row.indexOf('\t');
        rows.set(Number(row.slice(0, tab)), row);
      }
      skillRows = rows;
    }
    const out = {};
    for (const id of ids) {
      const row = skillRows.get(id);
      if (!row) continue;
      const m = row.split('\t');
      const params = walk(m.slice(29, 78).map((x) => Number(x) | 0));
      out[id] = {
        id,
        group: Number(m[1]) >>> 0,
        level: Number(m[2]) >>> 0,
        active: (Number(m[3]) >>> 0) !== 0,
        mastery: Number(m[4]) >>> 0,
        icon: m[18] || '',
        weapons: [Number(m[21]) >>> 0, Number(m[22]) >>> 0],
        mp: Number(m[24]) | 0,
        attack: !!params.att,
        durationMs: params.dura ? params.dura[0] >>> 0 : 0,
        heal: !!params.heal,
        area: !!params.efr,
      };
    }
    return out;
  }

  // refObjId -> [codename, display name, icon ddj] for every item the client knows
  // (missionPresentation.itemsByRefObjId + textdataname SN_ names, same lookup order
  // the client uses for its labels: exact, without the gender part, then shortened).
  async function itemCatalog() {
    const [mpRaw, namesRaw] = await Promise.all([bytesOf('/assets/data/missionPresentation.json'), bytesOf('/assets/text/textdataname.en.json')]);
    const mp = decodeJson(mpRaw.bytes);
    const names = decodeJson(namesRaw.bytes).entries || {};
    const nameOf = (code) => {
      const g = code.replace(/^ITEM_(CH|EU)_[MW]_/, 'ITEM_$1_');
      for (const c of [code, g]) if (names['SN_' + c] !== undefined) return names['SN_' + c];
      let p = g;
      while (p.includes('_')) {
        p = p.slice(0, p.lastIndexOf('_'));
        if (names['SN_' + p] !== undefined) return names['SN_' + p];
      }
      return code;
    };
    const out = {};
    for (const [id, v] of Object.entries(mp.itemsByRefObjId || {})) {
      if (!v || !v.codename) continue;
      out[id] = [v.codename, nameOf(v.codename), v.iconDdjPath || ''];
    }
    return out;
  }

  // Merged UI/text catalogue as the client builds it: {...textdataname, ...textuisystem}.
  async function textCatalog() {
    const [a, b] = await Promise.all([bytesOf('/assets/text/textdataname.en.json'), bytesOf('/assets/text/textuisystem.en.json')]);
    return Object.assign({}, decodeJson(a.bytes).entries || {}, decodeJson(b.bytes).entries || {});
  }

  // Trimmed /assets/char/roster.json (4.5 MB) for the wardrobe. items rows:
  // [refObjId, codename, equipSlot (-1 none), avatarSlot (-1 none), 'CH_M,CH_W,...'
  // (bodies with a drawn model), hasSoxGlow (0/1), armorClass]; models rows:
  // [refObjId, codename, isMount (0/1)]; aux: avatar ids with an extra model (wings).
  async function wardrobeCatalog() {
    const r = decodeJson((await bytesOf('/assets/char/roster.json')).bytes);
    const d = r.dress || {};
    const glows = d.specialGlows || {};
    const items = [];
    for (const [id, e] of Object.entries(d.equipment || {})) {
      if (!e || (e.slot == null && e.avatarSlot == null)) continue;
      const bodies = Object.keys(e.bodies || {}).filter((k) => e.bodies[k] && typeof e.bodies[k] === 'object');
      if (!bodies.length) continue;
      items.push([Number(id), e.code || '', e.slot == null ? -1 : e.slot, e.avatarSlot == null ? -1 : e.avatarSlot, bodies.join(','), glows[id] ? 1 : 0, e.armorClass || 0]);
    }
    const models = Object.values(r.models || {}).map((m) => [m.refObjId, m.codename || '', m.isMount ? 1 : 0]);
    return { items, models, aux: Object.keys(d.avatarAuxiliary || {}).map(Number) };
  }

  // Trimmed /assets/npc/manifest.json (13.7 MB): [refObjId, codename, kind] for every
  // monster, npc, cos (pets, horses, transport) and ride model.
  async function npcModels() {
    const m = decodeJson((await bytesOf('/assets/npc/manifest.json')).bytes);
    const out = [];
    for (const v of Object.values(m.models || {})) if (v && v.refObjId != null) out.push([v.refObjId, v.codename || '', v.kind || '']);
    return out;
  }

  // Lower-case asset paths under a prefix (e.g. every minimap tile the packs hold).
  async function list(prefix, suffix) {
    const m = await manifest();
    const pre = String(prefix || '').toLowerCase();
    const suf = String(suffix || '').toLowerCase();
    const out = [];
    for (const k of m.assets.keys()) if (k.startsWith(pre) && (!suf || k.endsWith(suf))) out.push(k);
    return out;
  }

  function report() {
    return { stats: Object.assign({}, stats), manifest: manifestInfo, manifestAgeMs: manifestAt ? Date.now() - manifestAt : -1, active: slots.n, queued: slots.q.length };
  }

  self.onmessage = async (e) => {
    const msg = (e && e.data) || {};
    if (msg.op === 'init') {
      ORIGIN = String(msg.origin || '');
      self.postMessage({ ready: true });
      return;
    }
    try {
      let result;
      switch (msg.op) {
        case 'ping':
          result = 'pong';
          break;
        case 'blob': {
          const { bytes, mime } = await bytesOf(msg.path);
          result = new Blob([bytes], { type: mime || (/\.png$/i.test(msg.path) ? 'image/png' : 'application/octet-stream') });
          break;
        }
        case 'json':
          result = decodeJson((await bytesOf(msg.path)).bytes);
          break;
        case 'skills':
          result = await skillInfo(msg.ids || []);
          break;
        case 'items':
          result = await itemCatalog();
          break;
        case 'texts':
          result = await textCatalog();
          break;
        case 'list':
          result = await list(msg.prefix, msg.suffix);
          break;
        case 'wardrobe':
          result = await wardrobeCatalog();
          break;
        case 'npcModels':
          result = await npcModels();
          break;
        case 'refresh':
          await manifest(true);
          result = report();
          break;
        case 'stats':
          result = report();
          break;
        default:
          throw fail('op', 'bilinmeyen istek: ' + msg.op);
      }
      self.postMessage({ id: msg.id, ok: true, result });
    } catch (err) {
      self.postMessage({ id: msg.id, ok: false, error: String((err && err.message) || err), code: (err && err.code) || '' });
    }
  };
}

const Assets = {
  mode: 'off', // 'worker' | 'page' | 'off'
  port: null, // {kind, post(msg), stop()}
  seq: 0,
  pending: new Map(), // id -> {op, payload, resolve, reject, timer}
  urls: new Map(), // path -> Promise<object URL | ''>
  images: new Map(), // path -> Promise<HTMLImageElement | null>
  fails: new Map(), // path -> {n, until, permanent, error}
  errors: [], // recent failures, newest last (diagnostics)
  skillMeta: new Map(),
  zones: null,
  bootError: '',
  timeouts: 0, // consecutive timeouts in worker mode
  okCount: 0,
  failCount: 0,

  boot() {
    if (this.port) return;
    if (this.mode === 'page' || !this.startWorker()) this.startPage();
  },

  startWorker() {
    let url = '';
    try {
      url = URL.createObjectURL(new Blob(['(' + assetLoaderMain.toString() + ')(self);'], { type: 'text/javascript' }));
      const w = new (Hook.NativeWorker || W.Worker)(url, { name: 'sro-asistan-assets' });
      const port = {
        kind: 'worker',
        alive: false,
        watch: 0,
        post: (m) => w.postMessage(m),
        stop: () => {
          clearTimeout(port.watch);
          w.onmessage = w.onerror = w.onmessageerror = null;
          try {
            w.terminate();
          } catch {}
          URL.revokeObjectURL(url);
        },
      };
      w.onmessage = (e) => {
        const d = e.data;
        if (d && d.ready) {
          port.alive = true;
          clearTimeout(port.watch);
          return;
        }
        this.reply(d);
      };
      w.onerror = (e) => {
        try {
          e.preventDefault();
        } catch {}
        this.fallback(T('worker hatası', 'worker error') + ': ' + (e.message || '?'));
      };
      w.onmessageerror = () => this.fallback(T('worker iletisi okunamadı', 'worker message could not be read'));
      port.watch = setTimeout(() => {
        if (!port.alive) this.fallback(T('worker 8 sn içinde yanıt vermedi', 'worker did not answer within 8 s'));
      }, 8000);
      this.port = port;
      this.mode = 'worker';
      w.postMessage({ op: 'init', origin: W.location.origin });
      return true;
    } catch (e) {
      if (url) URL.revokeObjectURL(url);
      this.bootError = String((e && e.message) || e);
      Log.warn('Varlık yükleyici worker başlatılamadı: ' + this.bootError);
      return false;
    }
  },

  startPage() {
    const host = { onmessage: null, postMessage: (d) => this.reply(d) };
    try {
      assetLoaderMain(host);
    } catch (e) {
      this.mode = 'off';
      this.bootError = String((e && e.message) || e);
      Log.error('Varlık yükleyici başlatılamadı: ' + this.bootError);
      return;
    }
    this.port = {
      kind: 'page',
      post: (m) => {
        Promise.resolve().then(() => host.onmessage({ data: m }));
      },
      stop() {},
    };
    this.mode = 'page';
    this.port.post({ op: 'init', origin: W.location.origin });
  },

  // Worker unusable: move to the page loader and replay what was waiting.
  fallback(reason) {
    if (this.mode !== 'worker') return;
    Log.warn(T('Varlık yükleyici sayfada çalışmaya geçti: ', 'Asset loader moved to the page: ') + reason);
    this.bootError = reason;
    this.port.stop();
    this.port = null;
    this.mode = 'page';
    this.startPage();
    if (!this.port) return;
    for (const [id, p] of this.pending) this.port.post({ id, op: p.op, ...p.payload });
  },

  reply(d) {
    if (!d || !d.id) return;
    const p = this.pending.get(d.id);
    if (!p) return;
    this.pending.delete(d.id);
    clearTimeout(p.timer);
    this.timeouts = 0;
    if (d.ok) {
      this.okCount++;
      p.resolve(d.result);
    } else {
      this.failCount++;
      const e = new Error(d.error || 'hata');
      e.code = d.code || '';
      this.note(p, e);
      p.reject(e);
    }
  },

  note(p, e) {
    this.errors.push({ at: Date.now(), op: p.op, path: p.payload?.path || '', code: e.code || '', error: e.message });
    if (this.errors.length > 40) this.errors.splice(0, this.errors.length - 40);
  },

  call(op, payload = {}, opts = {}) {
    this.boot();
    if (!this.port) {
      const e = new Error(T('varlık yükleyici çalışmıyor', 'asset loader is not running') + (this.bootError ? ' (' + this.bootError + ')' : ''));
      e.code = 'loader';
      return Promise.reject(e);
    }
    const id = ++this.seq;
    const ms = opts.timeout || (op === 'items' || op === 'texts' || op === 'skills' ? 150000 : 75000);
    return new Promise((resolve, reject) => {
      const entry = { op, payload, resolve, reject, timer: 0 };
      entry.timer = setTimeout(() => {
        if (!this.pending.has(id)) return;
        this.pending.delete(id);
        const e = new Error(T('zaman aşımı', 'timed out') + ' (' + op + (payload.path ? ' ' + payload.path : '') + ')');
        e.code = 'timeout';
        this.failCount++;
        this.note(entry, e);
        reject(e);
        // A worker that keeps timing out is stuck; the page loader takes over.
        if (this.mode === 'worker' && ++this.timeouts >= 3) this.fallback(T('3 istek zaman aşımına uğradı', '3 requests timed out'));
      }, ms);
      this.pending.set(id, entry);
      try {
        this.port.post({ id, op, ...payload });
      } catch (e) {
        clearTimeout(entry.timer);
        this.pending.delete(id);
        reject(e);
      }
    });
  },

  // Stops the loader, forgets every failure and starts again (diagnostics button).
  reset() {
    if (this.port) this.port.stop();
    this.port = null;
    this.mode = 'off';
    for (const [, p] of this.pending) {
      clearTimeout(p.timer);
      const e = new Error(T('yükleyici yeniden başlatıldı', 'loader restarted'));
      e.code = 'reset';
      p.reject(e);
    }
    this.pending.clear();
    for (const [path, p] of this.urls) {
      Promise.resolve(p)
        .then((u) => u && URL.revokeObjectURL(u))
        .catch(() => {});
      this.urls.delete(path);
    }
    this.images.clear();
    this.fails.clear();
    this.timeouts = 0;
    this.bootError = '';
    this.itemsPromise = this.textsPromise = this.zonesPromise = this.wardrobePromise = this.npcPromise = null;
    this.boot();
    bus.emit('assets-reset');
  },

  // Loader-side counters plus this side's state, for the diagnostics tab.
  async status() {
    let worker = null;
    try {
      worker = await this.call('stats', {}, { timeout: 6000 });
    } catch (e) {
      worker = { error: e.message };
    }
    return {
      mode: this.mode,
      bootError: this.bootError,
      pending: this.pending.size,
      ok: this.okCount,
      failed: this.failCount,
      urls: this.urls.size,
      fails: this.fails.size,
      errors: this.errors.slice(-12),
      worker,
    };
  },

  // True when the file is known to be absent from the game packs.
  isMissing(path) {
    return !!this.fails.get(path)?.permanent;
  },

  // "skill\\europe\\x.ddj" -> "/assets/images/Media_extracted/icon/skill/europe/x.png"
  iconPath(ddj) {
    if (!ddj) return '';
    let p = String(ddj).replace(/\\/g, '/').toLowerCase().replace(/^\/+/, '');
    if (p.startsWith('icon/')) p = p.slice(5);
    p = p.replace(/\.ddj$/, '.png');
    return '/assets/images/Media_extracted/icon/' + p;
  },

  // Resolves to an object URL, or '' while the file is unavailable. Failures are
  // retried after a backoff (4 s doubling up to 2 min); files absent from the packs
  // are re-checked after 10 minutes.
  url(path) {
    if (!path) return Promise.resolve('');
    const hit = this.urls.get(path);
    if (hit) return hit;
    const f = this.fails.get(path);
    if (f && now() < f.until) return Promise.resolve('');
    const p = this.call('blob', { path }).then(
      (blob) => {
        this.fails.delete(path);
        return URL.createObjectURL(blob);
      },
      (e) => {
        if (this.urls.get(path) === p) this.urls.delete(path);
        const n = (f?.n || 0) + 1;
        const permanent = e.code === 'missing';
        this.fails.set(path, { n, permanent, error: e.message, until: now() + (permanent ? 600000 : Math.min(120000, 4000 * 2 ** (n - 1))) });
        if (n === 1 && !permanent) Log.warn('Görsel yüklenemedi: ' + path + ' (' + e.message + ')');
        return '';
      }
    );
    this.urls.set(path, p);
    return p;
  },

  icon(ddj) {
    return this.url(this.iconPath(ddj));
  },

  // Sets an element's background to a packed image; a failed load is retried a few
  // times while the element still wants the same image.
  paint(el, attr, path, tries = 0) {
    el.dataset[attr] = path;
    this.url(path).then((u) => {
      if (el.dataset[attr] !== path) return;
      if (u) {
        el.style.backgroundImage = `url("${u}")`;
        return;
      }
      const f = this.fails.get(path);
      if (!f || f.permanent || tries >= 4) return;
      setTimeout(() => {
        if (el.dataset[attr] === path && (el.isConnected || tries < 2)) this.paint(el, attr, path, tries + 1);
      }, Math.max(1000, f.until - now() + 50));
    });
  },

  // Applies a loaded icon to an element as background image.
  applyIcon(el, ddj) {
    if (el) this.paint(el, 'icon', this.iconPath(ddj));
  },

  // Any packed image as an element background (same caching as icons).
  bg(el, path) {
    if (el && path) this.paint(el, 'bg', path);
  },

  // Promise of an HTMLImageElement for canvas drawing (null while unavailable; a
  // failed image is forgotten so the next call tries again).
  image(path) {
    const hit = this.images.get(path);
    if (hit) return hit;
    const p = this.url(path).then((u) =>
      u
        ? new Promise((resolve) => {
            const img = new Image();
            img.onload = () => resolve(img);
            img.onerror = () => resolve(null);
            img.src = u;
          })
        : null
    );
    this.images.set(path, p);
    p.then((img) => {
      if (!img && this.images.get(path) === p) this.images.delete(path);
    });
    return p;
  },

  async skills(ids) {
    const missing = ids.filter((id) => !this.skillMeta.has(id));
    if (missing.length) {
      try {
        const res = await this.call('skills', { ids: missing });
        for (const id of missing) this.skillMeta.set(id, res[id] || null);
        bus.emit('skillmeta');
      } catch (e) {
        Log.warn('Skill verisi okunamadı: ' + e.message);
      }
    }
    return ids.map((id) => this.skillMeta.get(id));
  },

  // refObjId -> [codename, name, iconDdj]; loaded once.
  itemCatalog() {
    this.itemsPromise ||= this.call('items').catch((e) => {
      Log.warn('Eşya kataloğu okunamadı: ' + e.message);
      this.itemsPromise = null;
      return {};
    });
    return this.itemsPromise;
  },

  // Wardrobe catalogue (see wardrobeCatalog in the loader); loaded once.
  wardrobe() {
    this.wardrobePromise ||= this.call('wardrobe', {}, { timeout: 150000 }).catch((e) => {
      Log.warn('Kıyafet kataloğu okunamadı: ' + e.message);
      this.wardrobePromise = null;
      return null;
    });
    return this.wardrobePromise;
  },

  // [refObjId, codename, kind] for monster / npc / cos / ride models; loaded once.
  npcModels() {
    this.npcPromise ||= this.call('npcModels', {}, { timeout: 150000 }).catch((e) => {
      Log.warn('Model listesi okunamadı: ' + e.message);
      this.npcPromise = null;
      return [];
    });
    return this.npcPromise;
  },

  // Game text catalogue (UIIT_*, PARAM_*, SN_* ...); loaded once.
  texts() {
    this.textsPromise ||= this.call('texts').catch((e) => {
      Log.warn('Oyun metinleri okunamadı: ' + e.message);
      this.textsPromise = null;
      return {};
    });
    return this.textsPromise;
  },

  // Zone names (regionId -> name), loaded once; concurrent callers share the promise.
  zoneNames() {
    if (this.zones) return Promise.resolve(this.zones);
    this.zonesPromise ||= this.call('json', { path: '/assets/text/textzonename.en.json' })
      .then((data) => {
        this.zones = data?.entries || {};
        bus.emit('zones');
        return this.zones;
      })
      .catch((e) => {
        Log.warn('Bölge adları okunamadı: ' + e.message);
        this.zonesPromise = null;
        return {};
      });
    return this.zonesPromise;
  },

  zoneName(regionId) {
    if (!this.zones) {
      this.zoneNames();
      return '';
    }
    return this.zones[String(regionId)] || '';
  },
};

// ---------------------------------------------------------------------------
// UI kit. Everything lives in one shadow root above the game canvas and is
// skinned with the game's own textures (window frame, buttons, tabs, check
// boxes, scroll bar, tooltip and notice art), so the windows read as part of
// the client rather than a separate popup.
// ---------------------------------------------------------------------------

// Bilingual text: T('Türkçe', 'English'). 'auto' picks Turkish for a Turkish
// browser and English for every other browser language.
function uiLang() {
  const l = Settings.global.lang;
  if (l === 'tr' || l === 'en') return l;
  const primary = (navigator.languages && navigator.languages[0]) || navigator.language || "";
  return /^tr(-|$)/i.test(primary) ? "tr" : "en";
}
const T = (tr, en) => (en != null && uiLang() === 'en' ? en : tr);

function h(tag, attrs, ...kids) {
  const el = document.createElement(tag);
  if (attrs) {
    for (const [k, v] of Object.entries(attrs)) {
      if (v == null || v === false) continue;
      if (k === 'class') el.className = v;
      else if (k === 'text') el.textContent = v;
      else if (k === 'style' && typeof v === 'object') Object.assign(el.style, v);
      else if (k === 'dataset') Object.assign(el.dataset, v);
      else if (k.startsWith('on') && typeof v === 'function') el.addEventListener(k.slice(2), v);
      else el.setAttribute(k, v === true ? '' : String(v));
    }
  }
  for (const c of kids.flat(Infinity)) {
    if (c == null || c === false) continue;
    el.append(c instanceof Node ? c : document.createTextNode(String(c)));
  }
  return el;
}

function isEditable(el) {
  if (!el || el.nodeType !== 1) return false;
  const tag = el.tagName;
  if (tag === 'TEXTAREA' || tag === 'SELECT') return true;
  if (tag === 'INPUT') return !['checkbox', 'radio', 'button', 'submit'].includes(el.type);
  return !!el.isContentEditable;
}

function skinVars() {
  let css = ':host{';
  for (const [k, v] of Object.entries(SKIN)) css += `--s-${k}:url("${v}");`;
  return css + '}';
}

