// ---- Diagnostics (Settings › Diagnostics) ------------------------------------
// Checks every layer the assistant depends on (game hook, asset loader, pack
// manifest, map/item/text data) and builds a report the user can copy and send.
const Diagnostics = {
  rows: [], // [{name, ok, detail, ms}]
  running: false,
  ranAt: 0,

  async run(onUpdate) {
    if (this.running) return;
    this.running = true;
    this.rows = [];
    const add = (name, ok, detail, ms) => {
      this.rows.push({ name, ok, detail: String(detail ?? ''), ms: ms == null ? null : Math.round(ms) });
      onUpdate();
    };
    const test = async (name, fn) => {
      const t = now();
      try {
        add(name, true, await fn(), now() - t);
      } catch (e) {
        add(name, false, (e && e.message) || e, now() - t);
      }
    };
    const lastError = (fallback) => Assets.errors.at(-1)?.error || fallback;
    onUpdate();
    try {
      add(
        T('Oyun bağlantısı', 'Game hook'),
        !!Hook.sim,
        Hook.sim
          ? (Hook.late ? T('geç bağlandı', 'attached late') : T('bağlı', 'attached')) + ' · ' + T('aşama', 'phase') + ': ' + World.phase
          : T('simülasyon worker’ı bulunamadı; sayfayı yenileyin', 'simulation worker not found; reload the page')
      );
      add(
        T('Varlık yükleyici', 'Asset loader'),
        Assets.mode !== 'off',
        (Assets.mode === 'worker' ? 'worker' : Assets.mode === 'page' ? T('sayfa (yedek)', 'page (fallback)') : T('kapalı', 'off')) + (Assets.bootError ? ' · ' + Assets.bootError : '')
      );
      await test(T('Paket manifesti', 'Pack manifest'), async () => {
        await Assets.call('list', { prefix: '/assets/data/', suffix: '.json' });
        const st = await Assets.call('stats', {}, { timeout: 8000 });
        const m = st.manifest || {};
        return `${m.assets} ${T('dosya', 'files')} · ${m.packs} ${T('paket', 'packs')} · ${m.format || '?'} · ${m.generatedAt || '?'}`;
      });
      await test(T('Harita karo listesi', 'Map tile list'), async () => {
        const mm = await Assets.call('json', { path: '/assets/data/mission-dungeon-minimap.json' });
        return `${mm?.tilePaths?.length || 0} ${T('karo', 'tiles')} · ${mm?.dungeons?.length || 0} ${T('zindan', 'dungeons')}`;
      });
      await test(T('Paketteki harita karoları', 'Map tiles in the packs'), async () => {
        const list = await Assets.call('list', { prefix: '/assets/images/media_extracted/minimap', suffix: '.png' });
        if (!list.length) throw new Error(T('hiç karo bulunamadı', 'no tiles found'));
        return `${list.length} ${T('karo', 'tiles')}`;
      });
      for (const [name, path] of [
        [T('Minimap karosu', 'Minimap tile'), '/assets/images/Media_extracted/minimap/100x100.png'],
        [T('Dünya haritası karosu', 'World map tile'), '/assets/images/Media_extracted/interface/worldmap/map/map_world_110x101.png'],
      ]) {
        await test(name, async () => {
          const blob = await Assets.call('blob', { path });
          return `${Math.round(blob.size / 1024)} KB · ${blob.type}`;
        });
      }
      await test(T('Bölge adları', 'Zone names'), async () => {
        const d = await Assets.call('json', { path: '/assets/text/textzonename.en.json' });
        return `${Object.keys(d?.entries || {}).length} ${T('bölge', 'zones')}`;
      });
      await test(T('Eşya kataloğu', 'Item catalogue'), async () => {
        const n = Object.keys(await Assets.itemCatalog()).length;
        if (!n) throw new Error(lastError(T('boş', 'empty')));
        return `${n} ${T('eşya', 'items')}`;
      });
      await test(T('Oyun metinleri', 'Game texts'), async () => {
        const n = Object.keys(await Assets.texts()).length;
        if (!n) throw new Error(lastError(T('boş', 'empty')));
        return `${n} ${T('metin', 'strings')}`;
      });
      await test(T('Skill verisi', 'Skill data'), async () => {
        const ids = (World.gp?.skills || []).slice(0, 5);
        const res = await Assets.call('skills', { ids: ids.length ? ids : [1, 2, 3] });
        return `${Object.keys(res || {}).length} / ${ids.length || 3}`;
      });
      await test(T('Oyunun önbelleği', 'Game cache'), async () => {
        const has = typeof caches !== 'undefined' && (await caches.has('sro-next-verified-v1'));
        return has ? T('var (dosyalar önce buradan okunur)', 'present (files are read from it first)') : T('yok', 'none');
      });
      add(T('Zamanlayıcı', 'Ticker'), true, Ticker.timer ? T('sayfa zamanlayıcısı', 'page timer') : 'worker');
      await test(T('Yükleyici sayaçları', 'Loader counters'), async () => {
        const s = (await Assets.call('stats', {}, { timeout: 8000 })).stats || {};
        return (
          `${T('istek', 'requests')} ${s.requests} · ${T('başarılı', 'ok')} ${s.ok} · ${T('hatalı', 'failed')} ${s.fail} · ` +
          `${T('önbellek', 'cache')} ${s.ownCache}+${s.gameCache}+${s.gamePack} · ${T('ağ', 'network')} ${s.range}+${s.transport} · ` +
          `${T('yeniden deneme', 'retries')} ${s.retries} · manifest ${s.manifestLoads}× · ${Math.round((s.bytes || 0) / 1048576)} MB`
        );
      });
    } finally {
      this.running = false;
      this.ranAt = Date.now();
      onUpdate();
    }
  },

  report() {
    const bundle = [...document.scripts].map((s) => s.src).find((s) => /\/index-[^/]+\.js/.test(s)) || '?';
    const lines = [
      `SRO Asistan ${VERSION} — ${T('tanılama', 'diagnostics')} ${new Date(this.ranAt || Date.now()).toISOString()}`,
      `${T('Tarayıcı', 'Browser')}: ${navigator.userAgent}`,
      `${T('Oyun paketi', 'Game bundle')}: ${bundle.slice(bundle.lastIndexOf('/') + 1)}`,
      '',
    ];
    for (const r of this.rows) lines.push(`[${r.ok ? 'OK' : T('HATA', 'FAIL')}] ${r.name}: ${r.detail}${r.ms != null ? ` (${r.ms} ms)` : ''}`);
    const errs = Assets.errors.slice(-10);
    if (errs.length) {
      lines.push('', T('Son yükleme hataları:', 'Recent load errors:'));
      for (const e of errs) lines.push(`${new Date(e.at).toISOString().slice(11, 19)} ${e.op} ${e.path} — ${e.code ? e.code + ': ' : ''}${e.error}`);
    }
    return lines.join('\n');
  },

  copy() {
    const text = this.report();
    const done = () => UI.toast(T('Rapor panoya kopyalandı', 'Report copied to clipboard'), 'info', 1800);
    const manual = () => {
      try {
        const ta = h('textarea', { style: { position: 'fixed', left: '-9999px' } });
        ta.value = text;
        document.body.append(ta);
        ta.select();
        document.execCommand('copy');
        ta.remove();
        done();
      } catch {
        UI.toast(T('Kopyalanamadı; metni elle seçin', 'Copy failed; select the text by hand'), 'warn', 2500);
      }
    };
    try {
      navigator.clipboard.writeText(text).then(done, manual);
    } catch {
      manual();
    }
  },

  render(content) {
    const lab = (t) => h('span', { class: 'ellip', style: { width: '112px', flex: '0 0 112px' }, title: t, text: t });
    const list = h('div', { class: 'col' });
    const out = h('textarea', { class: 'inp', readonly: 'readonly', spellcheck: 'false', style: { minHeight: '90px' } });
    const paint = () => {
      list.textContent = '';
      if (!this.rows.length && !this.running) list.append(h('div', { class: 'dim', text: T('Henüz çalıştırılmadı.', 'Not run yet.') }));
      for (const r of this.rows) {
        list.append(
          h(
            'div',
            { class: 'row', style: { alignItems: 'flex-start' } },
            h('span', { class: r.ok ? 'ok' : 'bad', style: { width: '14px', flex: '0 0 14px' }, text: r.ok ? '✔' : '✖' }),
            lab(r.name),
            h('span', { class: r.ok ? 'white grow' : 'bad grow', style: { wordBreak: 'break-word' }, text: r.detail }),
            h('span', { class: 'dim', style: { flex: '0 0 auto' }, text: r.ms != null ? r.ms + ' ms' : '' })
          )
        );
      }
      if (this.running) list.append(h('div', { class: 'dim', text: T('Denetleniyor…', 'Checking…') }));
      out.value = this.rows.length ? this.report() : '';
    };
    const start = () => this.run(() => list.isConnected && paint());
    content.append(
      box(
        T('Tanılama', 'Diagnostics'),
        h('div', { class: 'dim', text: T('Harita, ikonlar veya veriler yüklenmiyorsa buradaki sonuçları kopyalayıp gönderin.', 'If the map, icons or data do not load, copy these results and send them.') }),
        h(
          'div',
          { class: 'row wrap' },
          button(T('Yeniden denetle', 'Check again'), start),
          button(T('Raporu kopyala', 'Copy report'), () => this.copy()),
          button(
            T('Yükleyiciyi yeniden başlat', 'Restart the loader'),
            () => {
              Assets.reset();
              start();
            },
            { tip: T('Bekleyen yüklemeleri iptal eder, hata kayıtlarını siler ve yükleyiciyi yeniden kurar.', 'Cancels pending loads, forgets failures and starts the loader again.') }
          ),
          button(T('Manifesti yenile', 'Reload the manifest'), () =>
            Assets.call('refresh', {}, { timeout: 120000 }).then(
              () => {
                UI.toast(T('Manifest yenilendi', 'Manifest reloaded'), 'info', 1800);
                start();
              },
              (e) => UI.toast(T('Manifest yenilenemedi: ', 'Manifest reload failed: ') + e.message, 'warn', 3000)
            )
          )
        ),
        list
      ),
      box(T('Rapor', 'Report'), out)
    );
    paint();
    if (!this.rows.length && !this.running) start();
  },
};

Sections.settings = {
  icon: 'ic_alchemy',
  title: () => T('Ayarlar', 'Settings'),
  tab: 'general',

  build(root) {
    const content = h('div', { class: 'col grow scroll' });
    root.append(
      tabBar(
        [
          ['general', T('Genel', 'General')],
          ['keys', T('Kısayollar', 'Hotkeys')],
          ['profile', T('Profil', 'Profile')],
          ['gm', 'GM'],
          ['diag', T('Tanılama', 'Diagnostics')],
        ],
        () => this.tab,
        (k) => {
          this.tab = k;
          draw();
        }
      ),
      content
    );
    const G = () => Settings.global;
    const AL = () => Settings.profile.alerts;
    const lab = (t) => h('span', { style: { width: '150px', flex: '0 0 150px' }, text: t });
    const draw = () => {
      content.textContent = '';
      this.gmLog = null;
      if (this.tab === 'general') {
        content.append(
          box(
            T('Dil ve görünüm', 'Language and look'),
            h('div', { class: 'row wrap' }, lab(T('Dil', 'Language')), radio(T('Otomatik (tarayıcı)', 'Automatic (browser)'), 'auto', () => G().lang, (v) => setLang(v)), radio('Türkçe', 'tr', () => G().lang, (v) => setLang(v)), radio('English', 'en', () => G().lang, (v) => setLang(v))),
            h('div', { class: 'row' }, lab(T('Pencere saydamlığı', 'Window opacity')), slider(() => Math.round((G().uiOpacity ?? 1) * 100), (v) => ((G().uiOpacity = v / 100), UI.applyOpacity()), { min: 40, max: 100, fmt: (v) => v + '%' })),
            check(T('Skill barın üstündeki menü çubuğunu göster', 'Show the menu bar above the skill bar'), () => G().toolbar !== false, (v) => ((G().toolbar = v), Toolbar.place())),
            check(T('Minimap yanındaki küçük düğmeleri de göster', 'Also show the small buttons next to the minimap'), () => G().launcher, (v) => ((G().launcher = v), Launcher.place())),
            h('div', { class: 'row' }, button(T('Menü çubuğunu yerine koy', 'Reset the menu bar position'), () => ((G().toolbarOffset = null), (G().toolbarCollapsed = false), Settings.saveGlobal(), Toolbar.place()))),
            check(T('Av durum çubuğunu göster', 'Show the hunt status bar'), () => G().hud, (v) => ((G().hud = v), Hud.sync())),
            h('div', { class: 'row' }, button(T('Pencere konumlarını sıfırla', 'Reset window positions'), () => resetWindows()))
          ),
          box(
            T('Gizli oyuncular', 'Hidden players'),
            check(T('Görünmez GM’leri normal oyuncu gibi göster', 'Show invisible GMs like normal players'), () => Reveal.cfg().gm, (v) => ((Reveal.cfg().gm = v), Reveal.changed())),
            check(T('Gizlenen oyuncuları da göster (stealth, görünmezlik)', 'Also show stealthed / invisible players'), () => Reveal.cfg().stealth, (v) => ((Reveal.cfg().stealth = v), Reveal.changed())),
            h('div', {
              class: 'dim',
              text: T(
                'Yalnız sizin ekranınızda geçerlidir. Sunucu bu oyuncuların bilgisini gönderdiği sürece oyunda, minimapte, radarda ve haritada görünürler; radar ve haritada pembe işaretlenirler. Sunucu reddedeceği için hedef olarak seçilemezler.',
                'Applies to your screen only. As long as the server sends these players, they are drawn in the game, on the minimap, radar and map (marked pink on the radar and map). They cannot be targeted, because the server would refuse.'
              ),
            })
          ),
          box(
            T('Ses', 'Sound'),
            check(T('Uyarı sesleri', 'Alert sounds'), () => G().sound, (v) => (G().sound = v)),
            h('div', { class: 'row' }, lab(T('Ses düzeyi', 'Volume')), slider(() => Math.round((G().volume ?? 0.5) * 100), (v) => (G().volume = v / 100), { fmt: (v) => v + '%' }), button(T('Dene', 'Test'), () => Sound.play('notice')))
          ),
          box(
            T('Uyarılar', 'Alerts'),
            check(T('Unique ortaya çıkınca / ölünce', 'Unique appears / dies'), () => AL().unique, (v) => (AL().unique = v)),
            check(T('Fısıltı gelince', 'Incoming whisper'), () => AL().whisper, (v) => (AL().whisper = v)),
            check(T('Yakında GM görününce', 'GM nearby'), () => AL().gm, (v) => (AL().gm = v)),
            check(T('Can çok düşükken', 'Critical HP'), () => AL().lowHp, (v) => (AL().lowHp = v)),
            check(T('Envanter dolunca', 'Inventory full'), () => AL().invFull, (v) => (AL().invFull = v)),
            check(T('Karakter ölünce', 'Character death'), () => AL().death, (v) => (AL().death = v)),
            check(T('Eşya toplayınca (bildirim)', 'Item picked up (toast)'), () => AL().loot === true, (v) => (AL().loot = v))
          )
        );
      } else if (this.tab === 'keys') {
        const keyRow = (label, key) => {
          const btn = button(G().hotkeys[key] || T('(yok)', '(none)'), () => {
            btn.textContent = T('Bir tuşa basın… (Esc = kaldır)', 'Press a key… (Esc = clear)');
            Hotkeys.capture((code) => {
              const show = () => (btn.textContent = G().hotkeys[key] || T('(yok)', '(none)'));
              if (code !== 'Escape') {
                // onKey fires only the first matching action, so a duplicate would be silently dead.
                const clash = Object.keys(G().hotkeys).find((k) => k !== key && G().hotkeys[k] === code);
                if (clash) {
                  UI.toast(T('Bu tuş başka bir kısayolda kullanılıyor', 'This key is already used by another hotkey'), 'warn', 3000);
                  return show();
                }
                if (/^(Digit\d|Numpad\d|Key[A-Z]|Enter|NumpadEnter|Space|Tab|F[1-4]|F9|F10)$/.test(code))
                  UI.toast(T('Bu tuş oyunda da kullanılabilir; oyundaki işlevi engellenir', 'The game may also use this key; its game function will be blocked'), 'warn', 4000);
              }
              G().hotkeys[key] = code === 'Escape' ? '' : code;
              Settings.saveGlobal();
              show();
            });
          });
          btn.style.minWidth = '150px';
          return h('div', { class: 'row' }, lab(label), btn);
        };
        content.append(
          box(
            T('Kısayol tuşları', 'Hotkeys'),
            keyRow(T('Asistan penceresi', 'Assistant window'), 'main'),
            keyRow(T('Avı başlat / durdur', 'Start / stop hunting'), 'hunt'),
            keyRow(T('Radar', 'Radar'), 'radar'),
            keyRow(T('Av durum çubuğu', 'Hunt status bar'), 'hud'),
            ...Modules.list.filter((m) => m.hotkey).map((m) => keyRow(m.title(), m.hotkey))
          ),
          h('div', { class: 'dim small-text', text: T('Kısayollar sohbet kutusuna veya bir metin alanına yazarken çalışmaz. F1–F4 hızlı slot sayfaları, F9 kamera, F10 Item Mall olarak oyunda kullanılır; bunları seçmeyin. Rakam tuşları (hızlı slot), Enter ve oyunda bağlı harf tuşları da oyunda kullanılır.', 'Hotkeys are ignored while typing in chat or a text field. F1–F4 (quick slot pages), F9 (camera) and F10 (Item Mall) are used by the game. Digit keys (quick slots), Enter and letter keys bound in the game are also used by the game.') })
        );
      } else if (this.tab === 'profile') {
        const area = h('textarea', { class: 'inp', style: { minHeight: '120px' }, spellcheck: 'false' });
        content.append(
          box(
            T('Profil', 'Profile'),
            check(T('Her karakter için ayrı profil', 'Separate profile per character'), () => G().perCharacter, (v) => {
              G().perCharacter = v;
              Settings.useCharacter(World.charName);
            }),
            h('div', { class: 'row' }, lab(T('Etkin profil', 'Active profile')), h('span', { class: 'white', text: Settings.profileKey.replace('profile:', '') })),
            h('div', { class: 'row wrap' }, button(T('Profili sıfırla', 'Reset profile'), () => confirmBox(T('Bu karakterin makro/av/iksir ayarları sıfırlansın mı?', 'Reset macro/hunt/potion settings of this profile?'), () => Settings.resetProfile()), { cls: 'red' }))
          ),
          box(
            T('Dışa / içe aktar', 'Export / import'),
            area,
            h(
              'div',
              { class: 'row wrap' },
              button(T('Dışa aktar', 'Export'), () => {
                area.value = Settings.exportAll();
                area.select();
                try {
                  navigator.clipboard?.writeText(area.value);
                  UI.toast(T('Panoya kopyalandı', 'Copied to clipboard'), 'info', 1800);
                } catch {}
              }),
              button(T('İçe aktar', 'Import'), () => {
                try {
                  Settings.importAll(area.value);
                  UI.toast(T('Ayarlar yüklendi', 'Settings imported'), 'info', 2000);
                } catch (e) {
                  UI.toast(T('Geçersiz ayar metni', 'Invalid settings text'), 'warn', 2500);
                }
              })
            )
          )
        );
      } else if (this.tab === 'diag') {
        Diagnostics.render(content);
      } else {
        const gm = !!World.gp?.eligibility?.gm;
        if (!gm) {
          content.append(
            box(
              T('GM paneli', 'GM panel'),
              h('div', { class: 'white', text: T('Bu hesapta GM yetkisi yok.', 'This account has no GM privilege.') }),
              h('div', { class: 'dim', text: T('GM komutları (ışınlanma, eşya oluşturma, çağırma …) sunucu tarafında yetki ister. Oyun, yetki bayrağı (eligibility.gm) kapalıyken bu komutları zaten göndermez; yetkili bir hesapla girdiğinizde bu sekme etkinleşir.', 'GM commands (warp, make item, recall …) need server-side privilege. The client does not send them while eligibility.gm is off; this tab activates when you log in with a privileged account.') })
            )
          );
        } else {
          const line = h('input', { class: 'inp grow', placeholder: '/WORLDSTATUS' });
          line.addEventListener('keydown', (e) => e.key === 'Enter' && Cmd.gm(line.value) && (line.value = ''));
          const quick = h('div', { class: 'col' });
          for (const [cmd, label, arg] of GM_QUICK()) {
            const argEl = arg ? h('input', { class: 'inp', style: { width: '130px' }, placeholder: arg === 'name' ? T('oyuncu adı', 'player name') : arg === 'hour' ? '12' : 'ITEM_ETC_… 1' }) : null;
            quick.append(h('div', { class: 'row' }, h('span', { class: 'grow ellip', text: `${cmd} — ${label}` }), argEl, button(T('Gönder', 'Send'), () => Cmd.gm(argEl ? `${cmd} ${argEl.value.trim()}` : cmd))));
          }
          const warpBtn = button(T('Buranın /warp komutunu yaz', 'Fill /warp for this spot'), () => {
            const p = World.pose();
            if (p) line.value = `/warp ${p.regionId} ${Math.round(p.x)} ${Math.round(p.y)} ${Math.round(p.z)}`;
          });
          this.gmLog = h('div', { class: 'chatlog scroll', style: { minHeight: '80px', maxHeight: '140px', background: 'rgba(0,0,0,.35)', border: '1px solid #3a3020', padding: '2px' } });
          content.append(box(T('GM komutu', 'GM command'), h('div', { class: 'row' }, line, button(T('Gönder', 'Send'), () => Cmd.gm(line.value) && (line.value = ''))), h('div', { class: 'row' }, warpBtn)), box(T('Hızlı komutlar', 'Quick commands'), quick), box(T('GM yanıtları', 'GM replies'), this.gmLog));
        }
      }
    };
    draw();
    this.redraw = draw;
  },

  update() {
    if (!this.gmLog) {
      if (this.tab === 'gm' && World.gp?.eligibility?.gm && this.redraw) this.redraw();
      return;
    }
    const replies = World.gp?.gmReplies || [];
    const key = replies.length + ':' + (replies.at(-1)?.sequence ?? 0);
    if (key === this.gmKey) return;
    this.gmKey = key;
    this.gmLog.textContent = '';
    for (const r of replies) this.gmLog.append(h('div', { class: 'white', text: r.text || r.key || JSON.stringify(r) }));
    this.gmLog.scrollTop = this.gmLog.scrollHeight;
  },
};

// Yes/No confirmation (one reusable window so window state does not pile up).
function confirmBox(text, onYes) {
  let win = UI.wins.get('confirm');
  if (!win) win = new Win({ id: 'confirm', title: '', width: 300, height: 130, small: true });
  win.setTitle(T('Onay', 'Confirm'));
  win.body.textContent = '';
  win.body.append(
    h('div', { class: 'white center', style: { padding: '6px' }, text }),
    h(
      'div',
      { class: 'row center' },
      button(T('Evet', 'Yes'), () => {
        win.close();
        onYes();
      }),
      button(T('Hayır', 'No'), () => win.close())
    )
  );
  win.open();
}

// Older builds saved one window entry per confirmation ('confirm-<time>'); drop them once.
{
  const ws = Settings.global.windows || {};
  const stale = Object.keys(ws).filter((k) => k.startsWith('confirm-'));
  if (stale.length) {
    for (const k of stale) delete ws[k];
    Settings.saveGlobal();
  }
}

function resetWindows() {
  Settings.global.windows = {};
  Settings.saveGlobal();
  for (const w of UI.wins.values()) {
    if (w.resizable && w.defW) {
      w.w = w.defW;
      w.h = w.defH;
    }
    w.x = Math.round((innerWidth - w.w) / 2);
    w.y = Math.round((innerHeight - w.h) / 2);
    w.clampToView();
  }
  Hud.place(true);
}

function setLang(v) {
  Settings.global.lang = v;
  Settings.saveGlobal();
  Main.rebuild();
  Hud.rebuild();
  bus.emit('lang', uiLang());
}

