// ---- Tracking: drop sources, fresh drops, stack sizes ------------------------------------

const LootTrack = {
  src: new Map(), // ground gid -> { mobGid, mobRef, mobKind, mobName, mobLevel, cls, at }
  born: new Map(), // ground gid -> now() of a live drop (single spawn 12503, appear set)
  pendDrops: [], // { ref, mobRef, at } own-range despawns of known-source drops
  pendGains: [], // { ref, n, at } own inventory gains
  lastScan: 0,

  init() {
    bus.on('spawn', (e) => lootSafe(() => this.onSpawn(e), 'spawn'));
    bus.on('death', (e) => lootSafe(() => this.onDeath(e), 'death'));
    bus.on('despawn', (e) => lootSafe(() => this.onDespawn(e), 'despawn'));
    bus.on('gameplay', (gp, prev) => lootSafe(() => this.onGameplay(gp, prev), 'gameplay'));
    // Fallback for a claimant that reached the mirror through a later state event.
    bus.on('world', (f) => {
      if (!f || !f.ents || now() - this.lastScan < 400) return;
      this.lastScan = now();
      lootSafe(() => this.scan(), 'scan');
    });
    bus.on('reset', () => this.clear());
    bus.on('phase', (p) => {
      if (p !== 'world') this.clear();
    });
  },

  clear() {
    this.src.clear();
    this.born.clear();
    this.pendDrops = [];
    this.pendGains = [];
  },

  onSpawn(ev) {
    if (!ev || ev.kind !== 'ground-item' || !ev.gid) return;
    // The bus gets the (possibly display-rewritten) event entity; the mirror holds the real one.
    const e = World.ents.get(ev.gid) || ev;
    const gi = e.groundItem || {};
    if (gi.appear !== undefined) this.born.set(e.gid, now());
    if (gi.claimantGid) this.see(e);
    if (gi.appear !== undefined) LootAlert.onDrop(e);
    if (this.born.size > 600) this.prune();
  },

  see(e) {
    if (this.src.has(e.gid)) return;
    const mob = World.ents.get(e.groundItem.claimantGid);
    if (!mob) return;
    const info = {
      mobGid: mob.gid,
      mobRef: mob.refObjId,
      mobKind: mob.kind,
      mobName: mob.name || '',
      mobLevel: mob.level,
      cls: mob.kind === 'monster' ? monsterClass(mob) : '',
      at: now(),
    };
    this.src.set(e.gid, info);
    if (mob.kind === 'monster') DropDB.drop(e, mob);
  },

  scan() {
    for (const e of World.ents.values()) {
      if (e && e.kind === 'ground-item' && e.groundItem?.claimantGid && !this.src.has(e.gid)) this.see(e);
    }
  },

  prune() {
    for (const gid of this.born.keys()) if (!World.ents.has(gid)) this.born.delete(gid);
    for (const gid of this.src.keys()) if (!World.ents.has(gid)) this.src.delete(gid);
  },

  onDeath(e) {
    if (!e || e.kind !== 'monster') return;
    const mob = World.ents.get(e.gid) || e;
    if (dist2D(World.pose(), mob) <= LOOT_VIEW) DropDB.kill(mob);
  },

  onDespawn(e) {
    if (!e || e.kind !== 'ground-item') return;
    const s = this.src.get(e.gid);
    this.src.delete(e.gid);
    this.born.delete(e.gid);
    if (!s || s.mobKind !== 'monster' || !isNum(e.refObjId) || lootKind(lootTf(e)) === 'gold') return;
    if (!(dist2D(World.pose(), e) <= LOOT_VIEW)) return;
    const t = now();
    const i = this.pendGains.findIndex((g) => g.ref === e.refObjId && t - g.at < LOOT_PAIR_WINDOW);
    if (i >= 0) DropDB.qty(s.mobRef, e.refObjId, this.pendGains.splice(i, 1)[0].n);
    else this.pendDrops.push({ ref: e.refObjId, mobRef: s.mobRef, at: t });
    this.trim(t);
  },

  invTotals(gp) {
    const m = new Map();
    const add = (list) => {
      for (const it of Array.isArray(list) ? list : []) {
        if (!it || !isNum(it.refObjId)) continue;
        m.set(it.refObjId, (m.get(it.refObjId) || 0) + (isNum(it.quantity) && it.quantity > 0 ? it.quantity : 1));
      }
    };
    add(gp.inventory);
    for (const c of Array.isArray(gp.cosRecords) ? gp.cosRecords : []) add(c?.inventory);
    return m;
  },

  // Stack size of an own pickup: the despawn of a known-source drop paired with an
  // inventory gain of the same reference (shop and storage moves excluded).
  onGameplay(gp, prev) {
    if (!gp || !prev || !Array.isArray(gp.inventory) || !Array.isArray(prev.inventory) || !prev.inventory.length) return;
    if (!gp.localGid || gp.localGid !== prev.localGid || gp.shop || prev.shop || gp.storage || prev.storage) return;
    if (gp.inventory === prev.inventory && gp.cosRecords === prev.cosRecords) return;
    const a = this.invTotals(prev);
    const b = this.invTotals(gp);
    const t = now();
    for (const [ref, n] of b) {
      const d = n - (a.get(ref) || 0);
      if (d <= 0) continue;
      const i = this.pendDrops.findIndex((x) => x.ref === ref && t - x.at < LOOT_PAIR_WINDOW);
      if (i >= 0) DropDB.qty(this.pendDrops.splice(i, 1)[0].mobRef, ref, d);
      else this.pendGains.push({ ref, n: d, at: t });
    }
    this.trim(t);
  },

  trim(t) {
    this.pendDrops = this.pendDrops.filter((x) => t - x.at < LOOT_PAIR_WINDOW).slice(-100);
    this.pendGains = this.pendGains.filter((x) => t - x.at < LOOT_PAIR_WINDOW).slice(-100);
  },
};

// ---- SoX drop alert -------------------------------------------------------------------------

const LootAlert = {
  seen: new Set(),

  onDrop(e) {
    const cfg = lootCfg();
    if (!cfg.soxAlert || this.seen.has(e.gid) || lootKind(lootTf(e)) === 'gold') return;
    const check = () =>
      lootSafe(() => {
        if (this.seen.has(e.gid) || !World.ents.has(e.gid) || !Items.soxOf(e.refObjId)) return;
        const d = dist2D(World.pose(), e);
        if (!(d <= LOOT_SOX_RADIUS)) return;
        this.seen.add(e.gid);
        if (this.seen.size > 300) this.seen = new Set([...this.seen].slice(-150));
        const own = lootOwner(e);
        const src = LootTrack.src.get(e.gid);
        let text = T('SoX düştü: ', 'SoX dropped: ') + lootItemName(e.refObjId, e.name) + ' · ' + lootMeters(d);
        if (src) text += ' · ' + lootDropperText(src);
        if (own === 'other' || own === 'party-locked') text += T(' (başkasının)', " (someone else's)");
        UI.toast(text, '', 7000);
        if (cfg.soxSound) Sound.play('good');
        LootWin.dirty = true;
      }, 'sox-alert');
    if (Items.isLoaded()) check();
    else Items.ready().then(check, () => {});
  },
};

// ---- Observed drop database (IndexedDB 'sroAsistan-dropdb', memory fallback) ------------
// Record per monster refObjId:
//   { ref, name, level, kills: {cls: n}, items: {itemRef: {n, byClass, firstAt, lastAt, tf, name, qtyMin, qtyMax}},
//     gold: {cls: {n, min, max, sum}}, first, last }

const DropDB = {
  NAME: 'sroAsistan-dropdb',
  STORE: 'mobs',
  VER: 1,
  MAX_MOBS: 3000,
  MAX_ITEMS: 400,
  mobs: new Map(),
  dirty: new Set(),
  killed: new Map(), // monster gid -> now() once counted (kill and its drops count once)
  db: null,
  mode: 'loading', // loading | idb | memory
  rev: 0, // any change
  bulk: 0, // changes that touch many records at once (load, import, clear, storage mode)
  revOf: new Map(), // monster refObjId -> revision of its own record
  imports: new Map(), // source id -> last imported snapshot { ref: 'import:<source>', source, at, mobs }
  readyP: null,
  saveT: 0,
  writeFails: 0,

  ready() {
    return this.readyP || (this.readyP = this.openDb());
  },

  openDb() {
    return new Promise((resolve) => {
      let settled = false;
      let timer = 0;
      const finish = (ok, why) => {
        if (settled) return;
        settled = true;
        clearTimeout(timer);
        if (!ok) {
          this.mode = 'memory';
          if (why) Log.warn('Drop veritabanı açılamadı, kayıtlar yalnız bellekte tutulacak: ' + why);
        }
        this.changed();
        resolve(ok);
      };
      let idb = null;
      try {
        idb = W.indexedDB || (typeof indexedDB !== 'undefined' ? indexedDB : null);
      } catch (e) {
        return finish(false, e && e.message);
      }
      if (!idb) return finish(false, 'indexedDB yok');
      let req;
      try {
        req = idb.open(this.NAME, this.VER);
      } catch (e) {
        return finish(false, e && e.message);
      }
      timer = setTimeout(() => finish(false, 'zaman aşımı'), 10000);
      req.onupgradeneeded = () => {
        try {
          const db = req.result;
          if (!db.objectStoreNames.contains(this.STORE)) db.createObjectStore(this.STORE, { keyPath: 'ref' });
        } catch (e) {
          Log.warn('Drop veritabanı kurulamadı: ' + (e && e.message));
        }
      };
      req.onerror = () => finish(false, String(req.error?.message || req.error || 'open'));
      req.onsuccess = () => {
        const db = req.result;
        if (settled) {
          try {
            db.close();
          } catch {}
          return;
        }
        db.onversionchange = () => {
          try {
            db.close();
          } catch {}
          if (this.db === db) {
            this.db = null;
            this.mode = 'memory';
            this.changed();
          }
        };
        this.db = db;
        this.loadAll().then(
          () => {
            this.mode = 'idb';
            finish(true);
            if (this.dirty.size) this.schedule();
          },
          (e) => {
            this.db = null;
            try {
              db.close();
            } catch {}
            finish(false, e && e.message);
          }
        );
      };
    });
  },

  loadAll() {
    return new Promise((resolve, reject) => {
      try {
        const req = this.db.transaction(this.STORE, 'readonly').objectStore(this.STORE).getAll();
        req.onsuccess = () => {
          for (const raw of req.result || []) {
            if (typeof raw?.ref === 'string') {
              const snap = this.cleanSnapshot(raw);
              if (snap && !this.imports.has(snap.source)) this.imports.set(snap.source, snap);
              continue;
            }
            const rec = this.clean(raw);
            if (!rec) continue;
            // Data recorded in this session before the store finished loading is merged in.
            const mem = this.mobs.get(rec.ref);
            if (mem) {
              this.merge(rec, mem);
              this.dirty.add(rec.ref);
            }
            this.mobs.set(rec.ref, rec);
          }
          resolve();
        };
        req.onerror = () => reject(req.error || new Error('getAll'));
      } catch (e) {
        reject(e);
      }
    });
  },

  changed() {
    this.rev++;
    this.bulk++;
  },

  touch(ref) {
    this.dirty.add(ref);
    this.revOf.set(ref, (this.revOf.get(ref) || 0) + 1);
    this.rev++;
    this.schedule();
  },

  // Throttled, not debounced: a steady stream of kills must not keep postponing the write,
  // so dirty records reach the store at most 2.5 s after the first change.
  schedule() {
    if (this.mode !== 'idb' || this.saveT) return;
    this.saveT = setTimeout(() => {
      this.saveT = 0;
      this.flush();
    }, 2500);
  },

  flush() {
    clearTimeout(this.saveT);
    this.saveT = 0;
    if (!this.db || this.mode !== 'idb' || !this.dirty.size) return;
    const refs = [...this.dirty];
    this.dirty.clear();
    let once = false; // error and abort both fire for one failed transaction
    const failed = (e) => {
      if (once) return;
      once = true;
      for (const r of refs) this.dirty.add(r);
      if (++this.writeFails >= 3) {
        this.mode = 'memory';
        Log.warn('Drop veritabanına yazılamıyor, kayıtlar yalnız bellekte tutulacak: ' + (e && e.message ? e.message : e));
        this.changed();
      }
    };
    try {
      const tx = this.db.transaction(this.STORE, 'readwrite');
      const st = tx.objectStore(this.STORE);
      for (const ref of refs) {
        const r = typeof ref === 'string' ? this.imports.get(ref.slice(7)) : this.mobs.get(ref);
        if (r) st.put(r);
        else st.delete(ref);
      }
      tx.oncomplete = () => {
        this.writeFails = 0;
      };
      tx.onerror = () => failed(tx.error);
      tx.onabort = () => failed(tx.error);
    } catch (e) {
      failed(e);
    }
  },

  rec(mob) {
    const ref = mob.refObjId;
    if (!Number.isInteger(ref) || ref <= 0) return null;
    let r = this.mobs.get(ref);
    if (!r) {
      if (this.mobs.size >= this.MAX_MOBS) this.evict();
      r = { ref, name: '', level: 0, kills: {}, items: {}, gold: {}, first: Date.now(), last: Date.now() };
      this.mobs.set(ref, r);
    }
    if (mob.name) r.name = String(mob.name).slice(0, 64);
    if (isNum(mob.level) && mob.level > 0) r.level = mob.level;
    return r;
  },

  evict() {
    let oldest = null;
    for (const r of this.mobs.values()) if (!oldest || (r.last || 0) < (oldest.last || 0)) oldest = r;
    if (oldest) {
      this.mobs.delete(oldest.ref);
      this.dirty.add(oldest.ref);
    }
  },

  kill(mob) {
    if (!mob || mob.kind !== 'monster' || !mob.gid || this.killed.has(mob.gid)) return;
    const t = now();
    this.killed.set(mob.gid, t);
    if (this.killed.size > 2000) for (const [gid, at] of this.killed) if (t - at > 600000) this.killed.delete(gid);
    const r = this.rec(mob);
    if (!r) return;
    const cls = monsterClass(mob);
    r.kills[cls] = (r.kills[cls] || 0) + 1;
    r.last = Date.now();
    this.touch(r.ref);
  },

  // One ground item with a known monster source. Only monsters inside the kill radius count,
  // and their kill is counted here as well (spawn and death may arrive in either order).
  drop(item, mob) {
    if (!(dist2D(World.pose(), mob) <= LOOT_VIEW)) return;
    this.kill(mob);
    const r = this.rec(mob);
    if (!r || !isNum(item.refObjId)) return;
    const cls = monsterClass(mob);
    const tf = lootTf(item);
    const gi = item.groundItem || {};
    const stamp = Date.now();
    r.last = stamp;
    if (lootKind(tf) === 'gold') {
      const amount = Number(gi.goldAmount) || 0;
      if (amount <= 0) return;
      const g = (r.gold[cls] ||= { n: 0, min: 0, max: 0, sum: 0 });
      g.min = g.n ? Math.min(g.min, amount) : amount;
      g.max = Math.max(g.max, amount);
      g.sum += amount;
      g.n++;
    } else {
      let it = r.items[item.refObjId];
      if (!it) {
        if (Object.keys(r.items).length >= this.MAX_ITEMS) return;
        it = r.items[item.refObjId] = { n: 0, byClass: {}, firstAt: stamp, lastAt: stamp, tf, name: '', qtyMin: 0, qtyMax: 0 };
      }
      it.n++;
      it.byClass[cls] = (it.byClass[cls] || 0) + 1;
      it.lastAt = stamp;
      it.tf = tf;
      const nm = lootItemName(item.refObjId, item.name);
      if (nm && !nm.startsWith('#')) it.name = nm.slice(0, 80);
    }
    this.touch(r.ref);
  },

  qty(mobRef, itemRef, n) {
    const it = this.mobs.get(mobRef)?.items?.[itemRef];
    if (!it || !(n > 0) || n > 65535) return;
    it.qtyMin = it.qtyMin ? Math.min(it.qtyMin, n) : n;
    it.qtyMax = Math.max(it.qtyMax || 0, n);
    this.touch(mobRef);
  },

  // Sanitised copy of a stored or imported record (null when unusable).
  clean(raw) {
    if (!raw || typeof raw !== 'object') return null;
    const ref = Number(raw.ref);
    if (!Number.isInteger(ref) || ref <= 0 || ref > 0xffffffff) return null;
    const nn = (v) => {
      const x = Number(v);
      return Number.isFinite(x) && x > 0 ? Math.min(Math.floor(x), Number.MAX_SAFE_INTEGER) : 0;
    };
    const byCls = (o) => {
      const out = {};
      if (o && typeof o === 'object') for (const k of LOOT_CLASSES) if (nn(o[k])) out[k] = nn(o[k]);
      return out;
    };
    const rec = { ref, name: String(raw.name || '').slice(0, 64), level: Math.min(nn(raw.level), 255), kills: byCls(raw.kills), items: {}, gold: {}, first: nn(raw.first), last: nn(raw.last) };
    if (raw.items && typeof raw.items === 'object') {
      for (const [k, it] of Object.entries(raw.items).slice(0, this.MAX_ITEMS)) {
        const iref = Number(k);
        if (!Number.isInteger(iref) || iref <= 0 || !it || typeof it !== 'object' || !nn(it.n)) continue;
        rec.items[iref] = {
          n: nn(it.n),
          byClass: byCls(it.byClass),
          firstAt: nn(it.firstAt),
          lastAt: nn(it.lastAt),
          tf: (Number(it.tf) || 0) >>> 0,
          name: String(it.name || '').slice(0, 80),
          qtyMin: Math.min(nn(it.qtyMin), 65535),
          qtyMax: Math.min(nn(it.qtyMax), 65535),
        };
      }
    }
    if (raw.gold && typeof raw.gold === 'object') {
      for (const k of LOOT_CLASSES) {
        const g = raw.gold[k];
        if (g && typeof g === 'object' && nn(g.n)) rec.gold[k] = { n: nn(g.n), min: nn(g.min), max: nn(g.max), sum: nn(g.sum) };
      }
    }
    return rec;
  },

  // Adds the counts of src into dst (import and late store load).
  merge(dst, src) {
    if (!dst.name && src.name) dst.name = src.name;
    if (src.level) dst.level = Math.max(dst.level || 0, src.level);
    for (const [k, v] of Object.entries(src.kills || {})) dst.kills[k] = (dst.kills[k] || 0) + v;
    for (const [k, s] of Object.entries(src.items || {})) {
      const d = dst.items[k];
      if (!d) {
        if (Object.keys(dst.items).length < this.MAX_ITEMS) dst.items[k] = { ...s, byClass: { ...s.byClass } };
        continue;
      }
      d.n += s.n;
      for (const [c, v] of Object.entries(s.byClass || {})) d.byClass[c] = (d.byClass[c] || 0) + v;
      d.firstAt = d.firstAt && s.firstAt ? Math.min(d.firstAt, s.firstAt) : d.firstAt || s.firstAt;
      d.lastAt = Math.max(d.lastAt || 0, s.lastAt || 0);
      if (!d.tf) d.tf = s.tf;
      if (!d.name) d.name = s.name;
      if (s.qtyMin) d.qtyMin = d.qtyMin ? Math.min(d.qtyMin, s.qtyMin) : s.qtyMin;
      d.qtyMax = Math.max(d.qtyMax || 0, s.qtyMax || 0);
    }
    for (const [k, s] of Object.entries(src.gold || {})) {
      const d = dst.gold[k];
      if (!d) {
        dst.gold[k] = { ...s };
        continue;
      }
      d.min = d.n && s.n ? Math.min(d.min, s.min) : d.n ? d.min : s.min;
      d.max = Math.max(d.max, s.max);
      d.sum += s.sum;
      d.n += s.n;
    }
    dst.first = dst.first && src.first ? Math.min(dst.first, src.first) : dst.first || src.first;
    dst.last = Math.max(dst.last || 0, src.last || 0);
    return dst;
  },

  totalKills(r, cls) {
    if (!r) return 0;
    if (cls && cls !== 'all') return r.kills[cls] || 0;
    let n = 0;
    for (const v of Object.values(r.kills)) n += v;
    return n;
  },

  classesOf(r) {
    const set = new Set();
    if (r) {
      for (const [k, v] of Object.entries(r.kills)) if (v) set.add(k);
      for (const it of Object.values(r.items)) for (const k of Object.keys(it.byClass || {})) set.add(k);
      for (const k of Object.keys(r.gold)) set.add(k);
    }
    return LOOT_CLASSES.filter((k) => set.has(k));
  },

  summary(ref, cls = 'all') {
    const r = this.mobs.get(Number(ref));
    if (!r) return null;
    const kills = this.totalKills(r, cls);
    const items = [];
    let drops = 0;
    for (const [k, it] of Object.entries(r.items)) {
      const n = cls === 'all' ? it.n : it.byClass?.[cls] || 0;
      if (!n) continue;
      drops += n;
      items.push({
        ref: Number(k),
        n,
        rate: kills ? n / kills : null,
        name: lootItemName(Number(k), it.name),
        tf: it.tf,
        qtyMin: it.qtyMin || 0,
        qtyMax: it.qtyMax || 0,
        firstAt: it.firstAt,
        lastAt: it.lastAt,
        byClass: { ...it.byClass },
      });
    }
    items.sort((a, b) => b.n - a.n || a.name.localeCompare(b.name));
    let gold = null;
    for (const [k, g] of Object.entries(r.gold)) {
      if ((cls !== 'all' && k !== cls) || !g.n) continue;
      if (!gold) gold = { n: 0, min: g.min, max: g.max, sum: 0 };
      gold.n += g.n;
      gold.sum += g.sum;
      gold.min = Math.min(gold.min, g.min);
      gold.max = Math.max(gold.max, g.max);
    }
    if (gold) gold.avg = Math.round(gold.sum / gold.n);
    return {
      ref: r.ref,
      name: r.name,
      level: r.level,
      cls,
      kills,
      killsByClass: { ...r.kills },
      drops,
      goldDrops: gold ? gold.n : 0,
      gold,
      goldRate: gold && kills ? gold.n / kills : null,
      items,
      first: r.first,
      last: r.last,
    };
  },

  droppersOf(itemRef) {
    const out = [];
    for (const r of this.mobs.values()) {
      const it = r.items[itemRef];
      if (!it || !it.n) continue;
      const kills = this.totalKills(r);
      out.push({ mobRef: r.ref, name: r.name || '#' + r.ref, level: r.level, n: it.n, kills, rate: kills ? it.n / kills : null });
    }
    out.sort((a, b) => (b.rate ?? -1) - (a.rate ?? -1) || b.n - a.n);
    return out;
  },

  // Random id of this browser's database: counts are summed on import, so a file is
  // accepted once and never back into the browser that exported it.
  sourceId() {
    let id = Store.get('dropdb:source', '');
    if (!id) {
      id = Date.now().toString(36) + '-' + Math.random().toString(36).slice(2, 10);
      Store.set('dropdb:source', id);
    }
    return id;
  },

  exportJson() {
    return JSON.stringify({ format: 'sro-asistan-dropdb', version: 1, source: this.sourceId(), exportedAt: new Date().toISOString(), mobs: [...this.mobs.values()] });
  },

  // Exports are cumulative, so the last snapshot of every source is kept (in the same store,
  // under 'import:<source>'): a later file of that source replaces its earlier counts instead
  // of adding them twice. Files without a source id can only be summed.
  importJson(text) {
    const data = JSON.parse(text);
    const list = data && data.format === 'sro-asistan-dropdb' && Array.isArray(data.mobs) ? data.mobs : null;
    if (!list) throw new Error(T('tanınmayan dosya biçimi', 'unknown file format'));
    const source = typeof data.source === 'string' ? data.source.slice(0, 40) : '';
    if (source && source === this.sourceId()) throw new Error(T('bu dosya bu tarayıcının kendi kaydı', "this file is this browser's own record"));
    const at = String(data.exportedAt || '').slice(0, 40);
    const recs = [];
    for (const raw of list.slice(0, this.MAX_MOBS)) {
      const rec = this.clean(raw);
      if (rec) recs.push(rec);
    }
    if (!recs.length) throw new Error(T('dosyada geçerli kayıt yok', 'the file holds no valid record'));
    const prev = source ? this.imports.get(source) : null;
    if (prev && at && prev.at && at <= prev.at) throw new Error(T('bu kaynağın bu ya da daha yeni bir dosyası zaten içe aktarıldı', 'this file or a newer one of the same source was already imported'));
    if (prev) {
      for (const old of prev.mobs) {
        const cur = this.mobs.get(old.ref);
        if (!cur) continue;
        this.unmerge(cur, old);
        this.dirty.add(old.ref);
      }
    }
    for (const rec of recs) {
      const cur = this.mobs.get(rec.ref);
      if (cur) this.merge(cur, rec);
      else {
        if (this.mobs.size >= this.MAX_MOBS) this.evict();
        // A fresh copy: the snapshot below must not change with later kills.
        this.mobs.set(rec.ref, this.clean(rec));
      }
      this.dirty.add(rec.ref);
    }
    if (source) {
      const key = 'import:' + source;
      this.imports.set(source, { ref: key, source, at, mobs: recs });
      this.dirty.add(key);
    }
    this.changed();
    this.schedule();
    return recs.length;
  },

  // Removes the counts of src (an earlier import of the same source) from dst. Extremes
  // (min / max, first / last seen) cannot be taken back and stay.
  unmerge(dst, src) {
    const sub = (o, k, v) => {
      const x = (o[k] || 0) - (v || 0);
      if (x > 0) o[k] = x;
      else delete o[k];
    };
    for (const [k, v] of Object.entries(src.kills || {})) sub(dst.kills, k, v);
    for (const [k, s] of Object.entries(src.items || {})) {
      const d = dst.items[k];
      if (!d) continue;
      d.n -= s.n;
      for (const [c, v] of Object.entries(s.byClass || {})) sub(d.byClass, c, v);
      if (!(d.n > 0)) delete dst.items[k];
    }
    for (const [k, s] of Object.entries(src.gold || {})) {
      const d = dst.gold[k];
      if (!d) continue;
      d.n -= s.n;
      d.sum -= s.sum;
      if (!(d.n > 0) || !(d.sum > 0)) delete dst.gold[k];
    }
    return dst;
  },

  cleanSnapshot(raw) {
    if (!raw || typeof raw.ref !== 'string' || !raw.ref.startsWith('import:') || typeof raw.source !== 'string' || !Array.isArray(raw.mobs)) return null;
    const mobs = [];
    for (const m of raw.mobs.slice(0, this.MAX_MOBS)) {
      const rec = this.clean(m);
      if (rec) mobs.push(rec);
    }
    return { ref: 'import:' + raw.source, source: raw.source, at: String(raw.at || ''), mobs };
  },

  clear() {
    clearTimeout(this.saveT);
    this.saveT = 0;
    this.mobs.clear();
    this.dirty.clear();
    this.killed.clear();
    this.imports.clear();
    this.revOf.clear();
    this.changed();
    if (!this.db || this.mode !== 'idb') return;
    try {
      this.db.transaction(this.STORE, 'readwrite').objectStore(this.STORE).clear();
    } catch (e) {
      Log.warn('Drop veritabanı temizlenemedi: ' + (e && e.message));
    }
  },
};

// ---- Pick queue -------------------------------------------------------------------------
// One item in flight at a time. Next item when the current one despawns, the server refuses it
// (notice), or it times out (pet: the worker's 10 s COS deadline, character: walk time + 3 s).

const LOOT_REFUSALS = {
  UIIT_MSG_STRGERR_LOCKED_BY_OTHER_ONE: 'locked',
  UIIT_MSG_STRGERR_CANNOT_BE_PICKED: 'refused',
  UIIT_MSG_STRGERR_CANNOT_BE_PICKED_AT_QUEST_ACHIEVE_CONDITION: 'quest',
  UIIT_MSG_STRGERR_INVALID_TARGET: 'invalid',
  UIIT_STT_ERR_COMMON_INVALID_TARGET: 'invalid',
  UIIT_STT_ERR_COMMON_TOO_FAR: 'far',
  UIIT_MSG_STRGERR_INVENTORY_FULL: 'full',
  UIIT_MSG_COSPETERR_CANT_PICKITEM1: 'full',
  UIIT_MSG_COSPETERR_CANT_PICKITEM2: 'petfull',
  UIIT_MSG_COSPETERR_CANT_MOVETO_SUMITEM: 'petmove',
  UIIT_MSG_STRGERR_PARTY_INVENTORY_FULL: 'partyfull',
  UIIT_MSG_STRGERR_CANT_PICK_ITEM_WHILE_TELEPORT_WORK: 'teleport',
};

const LootPick = {
  running: false,
  single: false,
  queue: [],
  total: 0,
  done: 0,
  skipped: 0,
  cur: null, // { gid, ref, name, mode, sentAt, deadline, resends, resendAt, sawPending, clearedAt }
  priority: 0,
  ban: new Map(), // gid -> { until, why }
  locked: new Set(), // gids the server reported as another player's
  forceChar: new Set(),
  petBlockedUntil: 0,
  invFull: false,
  fullWarned: false,
  startedAt: 0,
  ownManualAt: -1,
  lastProgressAt: 0,
  lastPetAt: 0,
  pendingAt: 0, // last time a worker inventory transaction was seen pending
  lastYieldAt: 0,
  waitGid: 0, // item the queue is trying to send, and since when
  waitSince: 0,
  lastWhy: '',
  result: '',
  timer: 0,

  init() {
    bus.on('despawn', (e) => lootSafe(() => this.onDespawn(e), 'pick-despawn'));
    bus.on('notice', (n) => lootSafe(() => this.onNotice(n), 'pick-notice'));
    bus.on('death', (e) => {
      if (e && e.gid && e.gid === World.localGid()) this.stop(T('Karakter öldü', 'Character died'));
    });
    bus.on('phase', (p) => {
      if (p !== 'world') {
        this.stop('');
        this.ban.clear();
        this.locked.clear();
        this.forceChar.clear();
      }
    });
    bus.on('reset', () => this.stop(''));
  },

  banned(gid) {
    const b = this.ban.get(gid);
    if (!b) return null;
    if (now() > b.until) {
      this.ban.delete(gid);
      return null;
    }
    return b;
  },

  banFor(gid, ms, why) {
    this.ban.set(gid, { until: now() + ms, why });
    if (this.ban.size > 400) for (const [g, b] of this.ban) if (now() > b.until) this.ban.delete(g);
  },

  isQueued(gid) {
    return this.running && this.queue.includes(gid);
  },

  start(gids, single) {
    const list = [...new Set(gids)].filter((g) => Number.isInteger(g) && g > 0);
    if (!list.length) return;
    if (!World.inWorld() || World.isDead()) {
      UI.toast(T('Şu anda toplanamaz', 'Cannot pick up right now'), 'warn', 2000);
      return;
    }
    if (this.running && single) {
      // A click during a running queue: that item goes next.
      const gid = list[0];
      if (this.cur?.gid === gid) return;
      if (!this.queue.includes(gid)) {
        this.queue.unshift(gid);
        this.total++;
      }
      this.priority = gid;
      LootWin.dirty = true;
      return;
    }
    if (this.running) this.stop('');
    this.running = true;
    this.single = !!single;
    this.queue = list;
    this.total = list.length;
    this.done = 0;
    this.skipped = 0;
    this.cur = null;
    this.priority = single ? list[0] : 0;
    this.invFull = false;
    this.fullWarned = false;
    this.startedAt = now();
    this.ownManualAt = -1;
    this.lastProgressAt = now();
    this.result = '';
    clearInterval(this.timer);
    this.timer = setInterval(() => lootSafe(() => this.tick(), 'pick-tick'), 150);
    this.tick();
    LootWin.dirty = true;
  },

  stop(reason) {
    if (!this.running) return;
    this.running = false;
    clearInterval(this.timer);
    this.timer = 0;
    this.cur = null;
    this.queue = [];
    this.priority = 0;
    this.result = reason || '';
    if (reason && !this.single) UI.toast(reason, 'info', 2500);
    LootWin.dirty = true;
  },

  finish() {
    const single = this.single;
    const done = this.done;
    const total = this.total;
    const skipped = this.skipped;
    this.running = false;
    clearInterval(this.timer);
    this.timer = 0;
    this.cur = null;
    this.queue = [];
    this.priority = 0;
    if (single) {
      if (!done && this.lastWhy) UI.toast(T('Toplanamadı: ', 'Not picked up: ') + this.lastWhy, 'warn', 2500);
      this.result = done ? '' : this.lastWhy || '';
    } else {
      this.result = T(`Toplama bitti: ${done}/${total}`, `Picking done: ${done}/${total}`) + (skipped ? T(` · ${skipped} atlandı`, ` · ${skipped} skipped`) : '');
      UI.toast(this.result, 'info', 3000);
    }
    this.lastWhy = '';
    LootWin.dirty = true;
  },

  // Our commands bypass the game's command observer, so a running hunt would keep fighting
  // over the character; marking them as manual play makes the hunt engine yield meanwhile.
  yieldHunt() {
    if (typeof Hunt === 'undefined' || typeof Manual === 'undefined' || !Hunt.running) return;
    Manual.lastAt = now();
    Manual.kind = 'pickup';
    this.ownManualAt = Manual.lastAt;
    this.lastYieldAt = now();
  },

  tick() {
    if (!this.running) return;
    if (!World.inWorld()) return this.stop('');
    if (World.isDead()) return this.stop(T('Karakter öldü', 'Character died'));
    if (typeof Manual !== 'undefined' && Manual.lastAt > this.startedAt && Manual.lastAt !== this.ownManualAt && Manual.kind !== 'pickup') {
      return this.stop(T('Elle kontrol algılandı, toplama durdu', 'Manual control detected, picking stopped'));
    }
    const t = now();
    if (World.gp?.inventoryPending) this.pendingAt = t;
    const c = this.cur;
    if (c) {
      if (!World.ents.has(c.gid)) {
        this.cur = null;
        this.done++;
        this.lastProgressAt = t;
      } else {
        if (c.mode === 'pet') {
          // The worker keeps the inventory busy until the COS result (45165) arrives.
          if (World.gp?.inventoryPending) c.sawPending = true;
          else if (c.sawPending && !c.clearedAt) c.clearedAt = t;
          if (c.clearedAt && t - c.clearedAt > 1500) return this.fail(c, 15000, T('Pet toplayamadı', 'The pet could not pick it up'), true);
        } else if (c.resendAt && t >= c.resendAt && c.resends < 2) {
          // Sitting turns the first pickup into standing up; the worker ignores a repeat
          // of the same gid while the first one is still in progress.
          if (Cmd.pickup(c.gid)) {
            c.resends++;
            c.resendAt = c.resends < 2 ? t + 4000 : 0;
          }
        }
        if (t > c.deadline) return this.fail(c, 30000, T('Zaman aşımı', 'Timed out'), c.mode === 'pet');
        if (t - this.lastYieldAt > 2000) this.yieldHunt();
        return;
      }
    }
    const next = this.next();
    if (!next) {
      // Items still held for their dropper open within a few seconds.
      const waiting = this.queue.some((gid) => World.ents.get(gid)?.groundItem?.claimantGid);
      if (waiting && t - this.lastProgressAt < 12000) return;
      return this.finish();
    }
    this.send(next);
  },

  next() {
    const pose = World.pose();
    let best = null;
    let bestD = Infinity;
    for (let i = this.queue.length - 1; i >= 0; i--) {
      const gid = this.queue[i];
      const e = World.ents.get(gid);
      const drop = (why) => {
        this.queue.splice(i, 1);
        this.skipped++;
        if (why) this.lastWhy = why;
      };
      if (!e || e.kind !== 'ground-item') {
        drop(T('Eşya artık yerde değil', 'The item is gone'));
        continue;
      }
      const v = lootView(e, pose);
      if (v.own === 'other' || v.own === 'party-locked') {
        drop(T('Başka bir oyuncunun eşyası', "Another player's item"));
        continue;
      }
      if (v.ban) {
        drop(v.ban.why);
        continue;
      }
      if (!Number.isFinite(v.dist)) {
        drop(T('Ulaşılamıyor', 'Out of reach'));
        continue;
      }
      if (v.kind !== 'gold' && (this.invFull || World.freeBagSlots() === 0) && !this.petCanTake(gid, v)) {
        drop(T('Envanter dolu', 'Inventory full'));
        if (!this.fullWarned && !this.single) {
          this.fullWarned = true;
          UI.toast(T('Envanter dolu: yalnız altın toplanacak', 'Inventory full: only gold will be picked'), 'warn', 3000);
        }
        continue;
      }
      if (v.wait) continue;
      if (gid === this.priority) return v;
      if (v.dist < bestD) {
        bestD = v.dist;
        best = v;
      }
    }
    return best;
  },

  petFor(gid, v) {
    if (!lootCfg().usePet || this.forceChar.has(gid) || now() < this.petBlockedUntil) return null;
    const p = lootPet();
    if (!p || p.auto) return null;
    if (!(dist2D(p.ent, v.e || World.ents.get(gid)) <= LOOT_PET_REACH) || lootPressed()) return null;
    return v.kind === 'gold' || p.free > 0 ? p : null;
  },

  petCanTake(gid, v) {
    return !this.invFull && !!this.petFor(gid, v);
  },

  send(v) {
    const t = now();
    if (this.waitGid !== v.gid) {
      this.waitGid = v.gid;
      this.waitSince = t;
    }
    const pet = this.petFor(v.gid, v);
    let ok = false;
    if (pet) {
      // The worker refuses a COS pickup while any inventory command is pending; after one ends,
      // a short gap leaves room for potions and the player's own item use.
      if (World.gp?.inventoryPending) this.pendingAt = t;
      else if (t - this.lastPetAt >= 400 && t - this.pendingAt >= LOOT_PET_GAP) {
        ok = Cmd.raw({ kind: 'cos-pickup', gid: pet.rec.gid, target: v.gid }, T(`Pet topla: ${v.name}`, `Pet pick-up: ${v.name}`));
        if (ok) this.lastPetAt = t;
      }
    } else {
      ok = Cmd.pickup(v.gid);
    }
    if (!ok) {
      // Spacing or a busy inventory: the next tick tries again. A command that keeps being
      // held back (a guard, a stuck pending state) falls back to the character, then is skipped.
      if (t - this.waitSince > 6000) {
        this.waitSince = t;
        if (pet) this.forceChar.add(v.gid);
        else {
          const why = T('Komut gönderilemedi', 'The command could not be sent');
          const i = this.queue.indexOf(v.gid);
          if (i >= 0) this.queue.splice(i, 1);
          this.banFor(v.gid, 15000, why);
          this.skipped++;
          this.lastWhy = why;
          this.waitGid = 0;
        }
      }
      return;
    }
    this.waitGid = 0;
    const i = this.queue.indexOf(v.gid);
    if (i >= 0) this.queue.splice(i, 1);
    if (this.priority === v.gid) this.priority = 0;
    this.cur = {
      gid: v.gid,
      ref: v.ref,
      name: v.name,
      mode: pet ? 'pet' : 'char',
      sentAt: t,
      deadline: t + (pet ? 10500 : clamp(3000 + v.dist * 25, 3500, 20000)),
      resends: 0,
      resendAt: pet ? 0 : t + (World.isSitting() ? 1600 : 4000),
      sawPending: false,
      clearedAt: 0,
    };
    this.yieldHunt();
    LootWin.dirty = true;
  },

  // Current item failed: try it again with the character (pet failures) or skip it for a while.
  fail(c, banMs, why, retryChar) {
    this.cur = null;
    this.lastProgressAt = now();
    if (retryChar && c.mode === 'pet' && World.ents.has(c.gid) && !this.forceChar.has(c.gid)) {
      this.forceChar.add(c.gid);
      this.queue.unshift(c.gid);
      this.priority = c.gid;
    } else {
      this.banFor(c.gid, banMs, why);
      this.skipped++;
      this.lastWhy = why;
    }
    LootWin.dirty = true;
  },

  onDespawn(e) {
    if (!e || e.kind !== 'ground-item') return;
    LootWin.dirty = true;
    if (this.running && this.cur && e.gid === this.cur.gid) {
      this.cur = null;
      this.done++;
      this.lastProgressAt = now();
    }
  },

  onNotice(n) {
    const kind = LOOT_REFUSALS[String(n?.key || '')];
    const c = this.cur;
    if (!kind || !this.running || !c || now() - c.sentAt > 8000) return;
    switch (kind) {
      case 'locked':
        this.locked.add(c.gid);
        return this.fail(c, 120000, T('Başka bir oyuncunun eşyası', "Another player's item"), false);
      case 'refused':
        return this.fail(c, 60000, T('Sunucu toplamaya izin vermedi', 'The server refused the pickup'), false);
      case 'quest':
        return this.fail(c, 60000, T('Görev koşulu nedeniyle toplanamaz', 'Cannot be picked up (quest condition)'), false);
      case 'invalid':
      case 'far':
        return this.fail(c, 20000, kind === 'far' ? T('Çok uzak', 'Too far') : T('Geçersiz hedef', 'Invalid target'), true);
      case 'full':
        this.invFull = true;
        return this.fail(c, 15000, T('Envanter dolu', 'Inventory full'), false);
      case 'petfull':
        this.petBlockedUntil = now() + 60000;
        return this.fail(c, 15000, T('Pet envanteri dolu', 'Pet inventory full'), true);
      case 'petmove':
        return this.fail(c, 15000, T('Pet eşyaya gidemiyor', 'The pet cannot reach the item'), true);
      case 'partyfull':
        return this.stop(T('Parti envanteri dolu, toplama durdu', 'Party inventory full, picking stopped'));
      case 'teleport':
        return this.stop(T('Işınlanırken toplanamaz', 'Cannot pick up while teleporting'));
      default:
        return undefined;
    }
  },
};

// ---- Shared bits: game pager arrows ------------------------------------------------------------

function lootArrow(dir, onclick) {
  const base = LOOT_IMG + 'interface/ifcommon/com_' + dir + '_arrow';
  const layers = ['n', 'f', 'p', 'd'].map((k) => h('i', { class: k }));
  Assets.bg(layers[0], base + '.png');
  Assets.bg(layers[1], base + '_focus.png');
  Assets.bg(layers[2], base + '_press.png');
  Assets.bg(layers[3], base + '_disable.png');
  const el = h('div', { class: 'lt-arw', onclick }, layers);
  el.setDisabled = (off) => el.classList.toggle('dis', !!off);
  return el;
}

// ---- Ground items window ------------------------------------------------------------------------

const LootWin = {
  win: null,
  grid: null,
  cells: new Map(), // gid -> { el, ref, amt, mk, pt }
  list: [],
  page: 0,
  hover: 0,
  gridHover: false,
  sig: '',
  setSig: '',
  dirty: true,
  lastAt: 0,
  lang: '',

  init() {
    if (this.win) return;
    this.win = new Win({ id: 'pickup', title: T('Yer Eşyaları', 'Ground items'), width: 356, height: 446, resizable: true, minW: 340, minH: 380, x: 60, y: 110 });
    this.win.el.classList.add('lt-win');
    this.build();
    bus.on('world', (f) => {
      if (f && f.ents) this.dirty = true;
    });
    bus.on('phase', (phase, prev, left) => lootSafe(() => this.onPhase(phase, left), 'pickup-phase'));
    bus.on('items-ready', () => {
      this.cells.clear();
      this.dirty = true;
      this.sig = '';
    });
    setInterval(() => lootSafe(() => this.tick(), 'pickup-refresh'), 200);
    if (World.phase === 'world' && Settings.global.windows.pickup?.open) this.win.open();
  },

  // Closes with the game world and comes back with it (same rule as the main window).
  onPhase(phase, left) {
    if (phase === 'world') {
      if (Settings.global.windows.pickup?.open && !this.win.isOpen()) this.open();
    } else if (left && this.win.isOpen()) {
      this.win.close();
      (Settings.global.windows.pickup ||= {}).open = true;
      Settings.saveGlobal();
    }
    this.cells.clear();
    this.dirty = true;
  },

  open() {
    if (!this.win) return;
    this.win.open();
    this.refresh(true);
  },

  toggle() {
    if (!this.win) return;
    if (this.win.isOpen()) this.win.close();
    else this.open();
  },

  build() {
    const b = this.win.body;
    b.textContent = '';
    this.lang = uiLang();
    this.win.setTitle(T('Yer Eşyaları', 'Ground items'));
    this.cells.clear();
    this.sig = '';
    const refreshNow = () => {
      this.page = 0;
      this.refresh(true);
    };
    const tabs = tabBar(
      [
        ['all', T('Tümü', 'All')],
        ['gold', T('Altın', 'Gold')],
        ['equip', T('Ekipman', 'Gear')],
        ['sox', 'SoX'],
        ['other', T('Diğer', 'Other')],
      ],
      () => lootCfg().filter,
      (k) => {
        lootCfg().filter = k;
        Settings.saveGlobal();
        refreshNow();
      },
      true
    );
    tabs.style.flex = '0 0 24px';
    const sortSel = selectBox(
      [
        ['dist', T('Mesafeye göre', 'By distance')],
        ['value', T('Değere göre', 'By value')],
      ],
      () => lootCfg().sort,
      (v) => {
        lootCfg().sort = v;
        refreshNow();
      }
    );
    sortSel.setAttribute('data-tip', T('Değer sırası: SoX › mavi ekipman › ekipman (derece) › altın (miktar) › diğer › iksir', 'Value order: SoX › blue gear › gear (degree) › gold (amount) › other › potions'));
    const ownOnly = check(
      T('Yalnız benimkiler', 'Mine only'),
      () => lootCfg().ownOnly,
      (v) => {
        lootCfg().ownOnly = v;
        refreshNow();
      },
      T('Yalnız size ya da eşya paylaşımı açık partinize ait eşyalar', 'Only items of yours or of your item-sharing party')
    );
    const optBtn = button(T('Seçenek', 'Options'), (ev) => this.optionsMenu(ev));
    b.append(tabs, h('div', { class: 'lt-bar' }, sortSel, ownOnly, h('span', { class: 'sp' }), optBtn));

    this.grid = h('div', { class: 'lt-grid' });
    this.grid.addEventListener('pointerenter', () => (this.gridHover = true));
    this.grid.addEventListener('pointerleave', () => {
      this.gridHover = false;
      this.dirty = true;
    });
    b.append(this.grid);

    this.prev = lootArrow('left', () => {
      this.page = Math.max(0, this.page - 1);
      this.refresh(true);
    });
    this.next = lootArrow('right', () => {
      this.page++;
      this.refresh(true);
    });
    this.pageEl = h('span', { text: '1 / 1' });
    this.countEl = h('span', { class: 'lt-l' });
    this.goldEl = h('span', { class: 'lt-r' });
    b.append(h('div', { class: 'lt-pgrow' }, this.countEl, h('div', { class: 'lt-pager' }, this.prev, this.pageEl, this.next), this.goldEl));

    this.i1 = h('div');
    this.i2 = h('div', { class: 'dim' });
    b.append(h('div', { class: 'box flat lt-info' }, this.i1, this.i2));

    this.btnAll = button(T('Hepsini topla', 'Pick all'), () => this.pickAll(), {
      tip: T(
        'Görünen (süzgece uyan) ve size açık eşyaları en yakından başlayarak sırayla toplar. Başkalarının eşyaları atlanır; düşüreni ölmeyi bekleyen eşyalar açılınca toplanır.',
        'Picks the listed (filtered) items open to you one by one, nearest first. Other players’ items are skipped; items waiting for their dropper are picked once they open.'
      ),
    });
    this.btnStop = button(T('Durdur', 'Stop'), () => LootPick.stop(T('Toplama durduruldu', 'Picking stopped')), { cls: 'red' });
    this.statusEl = h('span', { class: 'grow ellip' });
    b.append(h('div', { class: 'lt-bar' }, this.btnAll, this.btnStop, this.statusEl));
    this.modeEl = h('div', { class: 'lt-mode' });
    b.append(this.modeEl);
    b.append(
      h('div', {
        class: 'lt-foot',
        text: T('Adet, artı (+) ve mavi seçenekler toplanmadan önce sunucudan gelmez.', 'Quantity, plus (+) and blue options are not sent before pickup.'),
      })
    );
    this.dirty = true;
  },

  optionsMenu(ev) {
    const c = lootCfg();
    const flip = (k) => () => {
      c[k] = !c[k];
      Settings.saveGlobal();
      this.refresh(true);
    };
    const mark = (on) => (on ? '✓' : '');
    const r = ev.currentTarget?.getBoundingClientRect?.() || { left: ev.clientX, bottom: ev.clientY };
    UI.menu(r.left, r.bottom + 2, [
      { header: T('Seçenekler', 'Options') },
      { label: T('Toplayıcı peti kullan', 'Use the grab pet'), hint: mark(c.usePet), action: flip('usePet') },
      { label: T('SoX düşünce uyar', 'Alert when SoX drops'), hint: mark(c.soxAlert), action: flip('soxAlert') },
      { label: T('Uyarıda ses çal', 'Play a sound with the alert'), hint: mark(c.soxSound), disabled: !c.soxAlert, action: flip('soxSound') },
      { label: T('Hedef çubuğunda drop düğmesi', 'Drop button in the target bar'), hint: mark(c.targetButton), action: flip('targetButton') },
      { sep: true },
      { header: T('“Hepsini topla” menzili', '“Pick all” range') },
      ...[
        [300, '30 m'],
        [600, '60 m'],
        [1000, '100 m'],
        [0, T('Görünen her yer', 'Everything in view')],
      ].map(([v, label]) => ({
        label,
        hint: mark(Number(c.range) === v),
        action: () => {
          c.range = v;
          Settings.saveGlobal();
          this.refresh(true);
        },
      })),
      { sep: true },
      { label: T('Drop envanteri', 'Drop inventory'), icon: skinIcon('ic_shop'), hint: Settings.global.hotkeys.drops || '', action: () => LootDropWin.toggle() },
    ]);
  },

  tick() {
    if (!this.win || !this.win.isOpen()) return;
    if (this.lang !== uiLang()) this.build();
    // Distances change while moving: a slow refresh even without entity events.
    if (this.dirty || now() - this.lastAt > 700) this.refresh(false);
  },

  collect() {
    const cfg = lootCfg();
    const pose = World.pose();
    const out = [];
    if (!World.gp) return out;
    for (const e of World.ents.values()) {
      if (!e || e.kind !== 'ground-item' || !e.gid) continue;
      const v = lootView(e, pose);
      if (lootPass(v, cfg)) out.push(v);
    }
    const rank = (v) => (v.pickable ? 0 : v.wait ? 1 : v.ban ? 2 : 3);
    const byValue = cfg.sort === 'value';
    for (const v of out) v.value = byValue ? lootValue(v) : 0;
    out.sort((a, b) => rank(a) - rank(b) || (byValue ? b.value - a.value : 0) || a.dist - b.dist || a.gid - b.gid);
    return out;
  },

  refresh(force) {
    if (!this.win || !this.win.isOpen()) return;
    this.dirty = false;
    this.lastAt = now();
    const list = this.collect();
    this.list = list;
    const gw = this.grid.clientWidth - 2;
    const gh = this.grid.clientHeight - 2;
    const cols = Math.max(1, Math.floor((gw + 3) / 39));
    const rows = Math.max(1, Math.floor((gh + 3) / 39));
    const per = cols * rows;
    const pages = Math.max(1, Math.ceil(list.length / per));
    this.page = clamp(this.page, 0, pages - 1);
    const slice = list.slice(this.page * per, this.page * per + per);
    const t = now();
    const setSig = slice
      .map((v) => v.gid)
      .sort((a, b) => a - b)
      .join(',');
    const sig = slice.map((v) => v.gid + ':' + v.ref + ':' + this.stateKey(v, t)).join(',') + '|' + per + '|' + uiLang();
    if (force || sig !== this.sig) {
      // While the pointer is over the grid the order is kept (sorting by distance would
      // shuffle the cells under the cursor); only the states are repainted.
      // this.sig stays at the drawn order, so the new order is applied once the pointer leaves.
      if (!force && this.gridHover && setSig === this.setSig) {
        for (const v of slice) {
          const c = this.cells.get(v.gid);
          if (c) this.paintCell(c, v, t);
        }
      } else {
        this.renderCells(slice, t, list.length);
        this.sig = sig;
        this.setSig = setSig;
      }
    }
    this.pageEl.textContent = `${this.page + 1} / ${pages}`;
    this.prev.setDisabled(this.page <= 0);
    this.next.setDisabled(this.page >= pages - 1);
    let gold = 0;
    let goldN = 0;
    for (const v of list) {
      if (v.kind === 'gold' && v.pickable) {
        gold += v.gold;
        goldN++;
      }
    }
    this.countEl.textContent = T(`${list.length} eşya`, `${list.length} items`);
    this.goldEl.textContent = goldN ? `${Items.goldText(gold)} ${Items.text('UIIT_STT_GOLD', 'Gold')}` : '';
    this.goldEl.style.color = goldN ? Items.goldColor(gold) : '';
    this.goldEl.dataset.tip = goldN ? T(`${goldN} altın yığını (toplayabildikleriniz)`, `${goldN} gold piles (ones you can take)`) : '';
    this.updInfo();
    this.updActions();
  },

  stateKey(v, t) {
    return [v.own, v.wait ? 1 : 0, v.ban ? 1 : 0, LootPick.isQueued(v.gid) ? 1 : 0, LootPick.cur?.gid === v.gid ? 1 : 0, v.born && t - v.born < 8000 ? 1 : 0, v.sox].join('');
  },

  renderCells(slice, t, total) {
    const nodes = [];
    for (const v of slice) {
      let c = this.cells.get(v.gid);
      if (!c || c.ref !== v.ref) {
        c = this.makeCell(v);
        this.cells.set(v.gid, c);
      }
      this.paintCell(c, v, t);
      nodes.push(c.el);
    }
    if (this.cells.size > 300) for (const gid of this.cells.keys()) if (!World.ents.has(gid)) this.cells.delete(gid);
    if (!nodes.length) {
      const text = !World.inWorld()
        ? T('Oyuna girdiğinizde yerdeki eşyalar burada görünür.', 'Ground items appear here once you are in game.')
        : total
          ? ''
          : lootCfg().filter !== 'all' || lootCfg().ownOnly
            ? T('Süzgece uyan eşya yok.', 'No item matches the filter.')
            : T('Yakında yerde eşya yok.', 'No items on the ground nearby.');
      nodes.push(h('div', { class: 'empty', text }));
    }
    this.grid.replaceChildren(...nodes);
  },

  makeCell(v) {
    const gid = v.gid;
    // Gold: no refObjId for itemSlot, so the catalogue icon cannot race the coin icon below.
    const item = v.kind === 'gold' ? { typeFlags: v.tf, groundItem: { typeFlags: v.tf, goldAmount: v.gold } } : v.e;
    const el = itemSlot(item, {
      size: 36,
      showQty: false,
      onclick: () => this.click(gid),
      oncontext: (ev) => this.menu(gid, ev),
      tip: () => lootSafe(() => this.tip(gid), 'tip') || '',
    });
    el.classList.add('lt-cell');
    if (v.kind === 'gold') Assets.bg(el, LOOT_GOLD_ICON);
    const amt = h('span', { class: 'lt-amt' });
    const mk = h('span', { class: 'lt-mk' });
    const pt = h('span', { class: 'lt-pt' });
    el.append(amt, mk, pt);
    el.addEventListener('pointerenter', () => {
      this.hover = gid;
      lootSafe(() => this.updInfo(), 'info');
    });
    el.addEventListener('pointerleave', () => {
      if (this.hover !== gid) return;
      this.hover = 0;
      lootSafe(() => this.updInfo(), 'info');
    });
    return { el, ref: v.ref, amt, mk, pt };
  },

  paintCell(c, v, t) {
    const q = LootPick.isQueued(v.gid);
    const cl = c.el.classList;
    cl.toggle('other', v.own === 'other' || v.own === 'party-locked');
    cl.toggle('wait', v.wait);
    cl.toggle('ban', !!v.ban);
    cl.toggle('cur', LootPick.cur?.gid === v.gid);
    cl.toggle('fresh', !!v.born && t - v.born < 8000);
    if (v.kind === 'gold') {
      c.amt.textContent = lootShortGold(v.gold);
      c.amt.style.color = Items.goldColor(v.gold);
    } else c.amt.textContent = '';
    c.mk.textContent = v.ban ? '×' : v.wait || q ? '•' : '';
    c.mk.style.color = v.ban ? '#ff7b62' : v.wait ? '#ffb84d' : '#7fe07f';
    c.pt.textContent = v.own === 'party' ? 'P' : '';
  },

  tip(gid) {
    const e = World.ents.get(gid);
    if (!e) return '';
    const v = lootView(e, World.pose());
    const root = Items.peerTooltip(e);
    const add = (text, color, small) => root.append(h('span', { class: 'tl' + (small ? ' small-text' : ''), style: { color: color || '' } }, text));
    root.append(h('span', { class: 'ts' }));
    if (v.kind === 'equip') {
      const d = lootDegree(v.ref);
      if (d) add(Items.text('UIIT_TOOLTIP_EQUIPMENT_CLASS', 'Degree: %d degrees').replace(/%d/, String(d)), Items.C.beige);
    }
    if (v.blue) add(T('Mavi seçenekli (değerleri toplanınca görünür)', 'Has magic options (shown after pickup)'), Items.C.blue);
    if (v.kind === 'potion' || v.kind === 'other') add(T('Adet toplanınca görünür', 'The quantity shows after pickup'), Items.C.dim, true);
    add(`${T('Mesafe', 'Distance')}: ${lootMeters(v.dist)} · ${lootKindLabel(v.kind)}`, Items.C.beige);
    const [ownText, ownColor] = lootOwnerText(v.own);
    add(LootPick.locked.has(gid) ? T('Sunucu: başka bir oyuncunun eşyası', "Server: another player's item") : ownText, ownColor);
    if (v.src) add(`${T('Düşüren', 'Dropped by')}: ${lootDropperText(v.src)}`, '#c7b88d');
    if (v.wait) add(T('Düşüren ölünce toplanabilir; oyun bu eşyayı henüz göstermiyor.', 'Can be picked up once its dropper dies; the game does not show it yet.'), '#ffb84d');
    if (v.ban) add(`${T('Atlandı', 'Skipped')}: ${v.ban.why}`, '#ff7b62');
    add(v.pickable ? T('Sol tık: topla · Sağ tık: menü', 'Left click: pick up · Right click: menu') : T('Sağ tık: menü', 'Right click: menu'), Items.C.dim, true);
    return root;
  },

  updInfo() {
    if (!this.i1) return;
    const e = this.hover ? World.ents.get(this.hover) : null;
    if (e) {
      const v = lootView(e, World.pose());
      this.i1.textContent = `${v.name} · ${lootMeters(v.dist)}`;
      this.i1.style.color = v.kind === 'gold' ? Items.goldColor(v.gold) : lootNameColor(v.ref, v.blue ? 1 : 0);
      const parts = [lootKindLabel(v.kind), lootOwnerText(v.own)[0]];
      if (v.wait) parts.push(T('düşüren ölünce açılır', 'opens when its dropper dies'));
      else if (v.src) parts.push(T('düşüren: ', 'dropped by ') + lootDropperText(v.src));
      if (v.ban) parts.push(v.ban.why);
      this.i2.textContent = parts.filter(Boolean).join(' · ');
      return;
    }
    const pick = this.list.filter((v) => v.pickable);
    const near = pick.length ? pick.reduce((a, b) => (b.dist < a.dist ? b : a)) : null;
    this.i1.style.color = '';
    this.i1.textContent = World.inWorld()
      ? T(`${pick.length} eşya toplanabilir`, `${pick.length} items can be picked up`) + (near ? T(` · en yakın: ${near.name} (${lootMeters(near.dist)})`, ` · nearest: ${near.name} (${lootMeters(near.dist)})`) : '')
      : T('Oyunda değilsiniz', 'Not in game');
    const others = this.list.filter((v) => v.own === 'other' || v.own === 'party-locked').length;
    const waiting = this.list.filter((v) => v.wait).length;
    const bits = [];
    if (others) bits.push(T(`${others} başkasının (soluk)`, `${others} someone else's (faded)`));
    if (waiting) bits.push(T(`${waiting} düşürenini bekliyor`, `${waiting} waiting for their dropper`));
    this.i2.textContent = bits.length ? bits.join(' · ') : T('İmleci bir eşyanın üstüne getirin.', 'Point at an item for details.');
  },

  // Items still held for their dropper are queued too: the queue skips them until they open
  // and waits for them up to 12 s without progress (LootPick.tick).
  candidates() {
    return this.list.filter((v) => (v.pickable || (v.wait && !v.ban && (v.own === 'mine' || v.own === 'party' || v.own === 'free') && Number.isFinite(v.dist))) && lootInRange(v));
  },

  updActions() {
    const n = this.candidates().length;
    const run = LootPick.running;
    this.btnAll.textContent = T(`Hepsini topla (${n})`, `Pick all (${n})`);
    this.btnAll.classList.toggle('dis', !n || (run && !LootPick.single));
    this.btnStop.classList.toggle('hidden', !run);
    if (run) {
      const c = LootPick.cur;
      const head = LootPick.single ? T('Toplanıyor', 'Picking') : `${LootPick.done}/${LootPick.total}`;
      this.statusEl.textContent = head + (c ? ` · ${c.name}${c.mode === 'pet' ? T(' (pet)', ' (pet)') : ''}` : '');
      this.statusEl.className = 'grow ellip white';
    } else {
      this.statusEl.textContent = LootPick.result || '';
      this.statusEl.className = 'grow ellip dim';
    }
    this.modeEl.textContent = this.modeText();
    this.modeEl.dataset.tip = T(
      'Toplayıcı pet (grab pet) çağrılıysa ve otomatik toplaması kapalıysa pete yakın eşyalar petle toplanır; uzaktaki eşyalara, saldırı altındayken ya da can iksir eşiğine yakınken karakter yürür (pet toplarken envanter meşgul kalır, iksir içilemez). Otomatik toplama açıkken oyunun kendi toplayıcısıyla çakışmamak için karakter kullanılır.',
      'With a summoned grab pet whose auto-grab is off, items close to the pet are picked by the pet; the character walks to farther items, and while under attack or near the potion HP threshold (a pet pickup keeps the inventory busy, so no potion can be used). While auto-grab is on the character is used so as not to collide with the game’s own picker.'
    );
  },

  modeText() {
    const p = lootCfg().usePet ? lootPet() : null;
    const free = World.freeBagSlots();
    const bag = isNum(free) ? T(` · çantada ${free} boş yer`, ` · ${free} free bag slots`) : '';
    if (!p) return T('Toplayan: karakter', 'Picker: character') + bag;
    if (p.auto) return T(`Toplayan: karakter (${p.name} kendi topluyor)`, `Picker: character (${p.name} grabs on its own)`) + bag;
    if (now() < LootPick.petBlockedUntil) return T(`Toplayan: karakter (${p.name} envanteri dolu)`, `Picker: character (${p.name} inventory full)`) + bag;
    return T(`Toplayan: ${p.name} (${p.free} boş)`, `Picker: ${p.name} (${p.free} free)`) + bag;
  },

  pickAll() {
    const list = this.candidates();
    if (!list.length) return;
    LootPick.start(
      list.map((v) => v.gid),
      false
    );
  },

  click(gid) {
    const e = World.ents.get(gid);
    if (!e) return;
    const v = lootView(e, World.pose());
    if (!v.pickable) {
      const why = v.ban
        ? v.ban.why
        : v.wait
          ? T('Düşüren ölünce toplanabilir', 'Can be picked up once its dropper dies')
          : v.own === 'other' || v.own === 'party-locked'
            ? T('Başka bir oyuncunun eşyası', "Another player's item")
            : T('Ulaşılamıyor', 'Out of reach');
      UI.toast(why, 'info', 1800);
      return;
    }
    if (v.kind !== 'gold' && World.freeBagSlots() === 0 && !LootPick.petCanTake(gid, v)) {
      UI.toast(T('Envanter dolu', 'Inventory full'), 'warn', 2000);
      return;
    }
    LootPick.start([gid], true);
  },

  menu(gid, ev) {
    const e = World.ents.get(gid);
    if (!e) return;
    const v = lootView(e, World.pose());
    const x = ev.clientX;
    const y = ev.clientY;
    const mob = v.src && v.src.mobKind === 'monster' ? v.src : null;
    UI.menu(x, y, [
      { header: v.name },
      { label: T('Topla', 'Pick up'), icon: skinIcon('ic_autoget'), disabled: !v.pickable, action: () => this.click(gid) },
      {
        label: T('Karakterle topla', 'Pick up with the character'),
        disabled: !v.pickable,
        action: () => {
          LootPick.forceChar.add(gid);
          this.click(gid);
        },
      },
      mob ? { label: T('Düşürenin drop envanteri', "Dropper's drop inventory"), icon: skinIcon('ic_shop'), action: () => MobDrops.open(mob.mobRef, { name: mob.mobName, level: mob.mobLevel, cls: mob.cls }) } : null,
      v.kind !== 'gold' ? { label: T('Bu eşyayı kim düşürür?', 'Who drops this item?'), action: () => LootDropWin.lookupItem(v.ref) } : null,
      typeof EntityMenu !== 'undefined' ? { sep: true } : null,
      typeof EntityMenu !== 'undefined' ? { label: T('Varlık menüsü…', 'Entity menu…'), action: () => setTimeout(() => lootSafe(() => EntityMenu.open(World.ents.get(gid) || gid, x, y), 'entity-menu'), 0) } : null,
    ]);
  },
};

// ---- Observed-drop tooltip and compact summary card -----------------------------------------------

// Tooltip of one observed item (it = DropDB.summary() item) of monster mobRef.
function lootDropTip(mobRef, it, kills, cls) {
  const tf = it.tf >>> 0;
  const root = Items.peerTooltip({ refObjId: it.ref, typeFlags: tf, groundItem: { typeFlags: tf } });
  const add = (text, color, small) => root.append(h('span', { class: 'tl' + (small ? ' small-text' : ''), style: { color: color || '' } }, text));
  const d = ItemType.isEquipment(tf) ? lootDegree(it.ref) : 0;
  if (d) add(Items.text('UIIT_TOOLTIP_EQUIPMENT_CLASS', 'Degree: %d degrees').replace(/%d/, String(d)), Items.C.beige);
  root.append(h('span', { class: 'ts' }));
  add(T('Gözlem', 'Observed') + `: ${fmtInt(it.n)} / ${fmtInt(kills)} ${T('öldürme', 'kills')} (${lootPct(it.rate)})`, '#ffd65a');
  if (!cls || cls === 'all') {
    const r = DropDB.mobs.get(mobRef);
    for (const [k, n] of Object.entries(it.byClass || {})) {
      const kk = r?.kills?.[k] || 0;
      add(`${lootClassLabel(k)}: ${fmtInt(n)} / ${fmtInt(kk)} (${lootPct(kk ? n / kk : null)})`, '#efdaa4');
    }
  }
  if (it.qtyMax) add(T(`Adet (kendi topladıklarınız): ${it.qtyMin}–${it.qtyMax}`, `Quantity (your own pickups): ${it.qtyMin}–${it.qtyMax}`), '#efdaa4');
  add(T('Son görülme: ', 'Last seen: ') + lootAgo(it.lastAt), Items.C.dim, true);
  add(T('Tık: bu eşyayı düşüren tüm canavarlar', 'Click: every monster that drops this item'), Items.C.dim, true);
  return root;
}

// Compact card for other windows (bestiary detail): kill count, the most frequent observed
// items, gold range and a button to the full drop inventory. Always a Node.
function lootSummaryNode(ref, cls = 'all') {
  const s = DropDB.summary(ref, cls);
  const open = button(T('Drop envanteri', 'Drop inventory'), () => MobDrops.open(ref));
  const head = h(
    'div',
    { class: 'ld-sum-h' },
    h('b', { text: T('Gözlenen düşüşler', 'Observed drops') }),
    h('span', { class: 'dim ellip', text: s ? T(`${fmtInt(s.kills)} öldürme`, `${fmtInt(s.kills)} kills`) : T('henüz gözlem yok', 'no observations yet') }),
    h('span', { class: 'sp' }),
    open
  );
  const card = h('div', { class: 'ld-sum' }, head);
  if (s && s.items.length) {
    const grid = h('div', { class: 'ld-sum-g' });
    for (const it of s.items.slice(0, 8)) {
      const tf = it.tf >>> 0;
      const slot = itemSlot({ refObjId: it.ref, typeFlags: tf, groundItem: { typeFlags: tf } }, { size: 30, showQty: false, tip: () => lootSafe(() => lootDropTip(ref, it, s.kills, cls), 'sum-tip') || '' });
      slot.addEventListener('click', () => MobDrops.lookupItem(it.ref));
      grid.append(h('div', { class: 'ld-cell' }, slot, h('b', null, h('em', { text: fmtInt(it.n) }), s.kills ? '/' + fmtInt(s.kills) : '')));
    }
    card.append(grid);
    if (s.items.length > 8) card.append(h('div', { class: 'dim small-text', text: T(`+${s.items.length - 8} eşya daha`, `+${s.items.length - 8} more items`) }));
  }
  if (s && s.gold) {
    const coin = h('i', { class: 'ld-coin' });
    Assets.bg(coin, LOOT_GOLD_ICON);
    card.append(h('div', { class: 'ld-stat' }, coin, h('span', { style: { color: Items.goldColor(s.gold.max) }, text: `${Items.goldText(s.gold.min)} – ${Items.goldText(s.gold.max)}` }), h('span', { class: 'dim', text: `(${lootPct(s.goldRate)})` })));
  }
  card.data = s; // the plain numbers for callers that want them
  return card;
}

// ---- Drop inventory window ------------------------------------------------------------------------

const LootDropWin = {
  win: null,
  ref: 0, // monster refObjId, 0 = list of known monsters
  ctx: null, // { name, level, rarity, party, cls } of the live target it was opened for
  cls: 'all',
  query: '',
  lookRef: 0, // item refObjId of a reverse lookup
  lastTargetGid: 0,
  sig: '',
  viewSig: '', // sig without the data revision
  drawnAt: 0,
  hovering: false, // pointer over the list: data-only redraws wait until it leaves
  userAt: 0, // last click / scroll inside the window: following the target pauses meanwhile
  lang: '',
  hoverText: null,
  nameCache: new Map(),

  init() {
    if (this.win) return;
    this.win = new Win({ id: 'drops', title: T('Drop envanteri', 'Drop inventory'), width: 380, height: 520, resizable: true, minW: 330, minH: 420, x: 430, y: 90 });
    this.win.el.classList.add('lt-win');
    const busy = () => (this.userAt = now());
    this.win.el.addEventListener('pointerdown', busy, true);
    this.win.el.addEventListener('wheel', busy, { capture: true, passive: true });
    this.build();
    bus.on('phase', (phase, prev, left) =>
      lootSafe(() => {
        if (phase === 'world') {
          if (Settings.global.windows.drops?.open && !this.win.isOpen()) this.open(this.ref, this.ctx);
        } else if (left && this.win.isOpen()) {
          this.win.close();
          (Settings.global.windows.drops ||= {}).open = true;
          Settings.saveGlobal();
        }
      }, 'drops-phase')
    );
    bus.on('items-ready', () => (this.sig = ''));
    setInterval(() => lootSafe(() => this.tick(), 'drops-refresh'), 250);
    if (World.phase === 'world' && Settings.global.windows.drops?.open) this.open(0);
  },

  build() {
    const b = this.win.body;
    b.textContent = '';
    this.lang = uiLang();
    this.sig = '';
    // Back: from a search to the monster it started from, from a monster to the list.
    this.backBtn = button('◂', () => {
      if (this.query || this.lookRef) {
        this.query = '';
        this.lookRef = 0;
        this.search.value = '';
        this.sig = '';
        this.refresh();
      } else this.open(0);
    });
    this.iconEl = h('i', { class: 'ld-ic' });
    this.nameEl = h('span', { class: 'ld-nm' });
    this.lvEl = h('span', { class: 'ld-lv' });
    this.clsEl = h('span', { class: 'ld-cl' });
    b.append(h('div', { class: 'ld-head' }, this.backBtn, this.iconEl, this.nameEl, this.lvEl, this.clsEl));
    this.tabsHost = h('div', { class: 'ld-tabhost', style: { flex: '0 0 auto' } });
    b.append(this.tabsHost);
    this.coinEl = h('i', { class: 'ld-coin' });
    Assets.bg(this.coinEl, LOOT_GOLD_ICON);
    this.statEl = h('span', { class: 'lt-l' });
    this.goldEl = h('span', { class: 'white' });
    b.append(h('div', { class: 'ld-stat' }, this.statEl, this.coinEl, this.goldEl));
    this.scroll = h('div', { class: 'scroll ld-scroll' });
    this.scroll.addEventListener('pointerenter', () => (this.hovering = true));
    this.scroll.addEventListener('pointerleave', () => (this.hovering = false));
    this.hovering = false;
    b.append(this.scroll);
    this.i1 = h('div');
    this.i2 = h('div', { class: 'dim' });
    b.append(h('div', { class: 'box flat lt-info' }, this.i1, this.i2));
    this.search = h('input', { class: 'inp grow', placeholder: T('Eşya ya da canavar ara (bu eşyayı kim düşürür?)', 'Search an item or monster (who drops this item?)'), spellcheck: 'false' });
    const onSearch = debounce(() => {
      this.lookRef = 0;
      this.query = this.search.value || '';
      this.sig = '';
      lootSafe(() => this.refresh(), 'drops-search');
    }, 200);
    this.search.value = this.lookRef ? lootItemName(this.lookRef, '') : this.query;
    this.search.addEventListener('input', onSearch);
    this.clearSearch = button('×', () => {
      this.search.value = '';
      this.query = '';
      this.lookRef = 0;
      this.sig = '';
      this.refresh();
    }, { tip: T('Aramayı temizle', 'Clear search') });
    this.followChk = check(
      T('Hedefi izle', 'Follow target'),
      () => lootCfg().dropsFollow,
      (v) => {
        lootCfg().dropsFollow = v;
        this.userAt = 0;
        this.lastTargetGid = -1; // follow the current selection right away
      },
      T(
        'Seçili canavar değişince pencere onun düşüşlerini gösterir. Pencerede tıklayıp gezinirken 15 saniye izlemez.',
        'Shows the drops of the selected monster when the selection changes. Pauses for 15 seconds while you click or scroll in the window.'
      )
    );
    b.append(h('div', { class: 'lt-bar' }, this.search, this.clearSearch, this.followChk));
    this.storeEl = h('span', { class: 'grow ellip dim small-text' });
    this.clearBtn = button(T('Temizle', 'Clear'), () => this.confirmClear(), { tip: T('Tüm gözlem kayıtlarını siler', 'Deletes every observation') });
    b.append(
      h(
        'div',
        { class: 'lt-bar' },
        button(T('Dışa aktar', 'Export'), () => this.exportFile(), { tip: T('Kayıtları JSON dosyası olarak indirir', 'Downloads the records as a JSON file') }),
        button(T('İçe aktar', 'Import'), () => this.importFile(), { tip: T('JSON dosyasındaki kayıtları mevcutlarla birleştirir; aynı kaynaktan gelen yeni bir dosya öncekinin yerini alır', 'Merges the records of a JSON file into the current ones; a newer file of the same source replaces the earlier one') }),
        this.clearBtn,
        this.storeEl
      )
    );
    b.append(
      h('div', {
        class: 'lt-foot',
        text: T('Gözlenen düşüşler: sunucunun drop tablosu istemcide yok; liste avladıkça dolar.', 'Observed drops: the server’s drop table is not in the client; the list fills as you hunt.'),
      })
    );
  },

  // ctx (optional): { name, level, rarity, party, cls } of the live monster it is opened for.
  open(ref, ctx) {
    if (!this.win) return;
    this.show(ref, ctx);
    this.win.open();
    this.refresh();
  },

  // Switches the shown monster without bringing the window to the front (target following).
  show(ref, ctx) {
    this.ref = Number(ref) || 0;
    this.ctx = this.ref && ctx && typeof ctx === 'object' ? ctx : null;
    // The target's grade when it has observations of its own, else every grade.
    const c = this.ctx?.cls;
    this.cls = c && LOOT_CLASSES.includes(c) && DropDB.mobs.get(this.ref)?.kills?.[c] ? c : 'all';
    this.query = '';
    this.lookRef = 0;
    if (this.search) this.search.value = '';
    const t = World.target();
    if (t) this.lastTargetGid = t.gid;
    this.sig = '';
  },

  lookupItem(itemRef) {
    if (!this.win) return;
    this.lookRef = Number(itemRef) || 0;
    this.query = '';
    if (this.search) this.search.value = lootItemName(this.lookRef, '');
    this.sig = '';
    this.win.open();
    this.refresh();
  },

  toggle() {
    if (!this.win) return;
    if (this.win.isOpen()) return this.win.close();
    const t = World.target();
    if (t && t.kind === 'monster') this.open(t.refObjId, lootMobCtx(t));
    else this.open(this.ref);
  },

  tick() {
    if (!this.win || !this.win.isOpen()) return;
    if (this.lang !== uiLang()) this.build();
    // Follow the selected monster (only when the selection itself changes).
    const t = World.target();
    const tg = t ? t.gid : 0;
    if (tg !== this.lastTargetGid) {
      this.lastTargetGid = tg;
      if (lootCfg().dropsFollow && now() - this.userAt > 15000 && t && t.kind === 'monster' && !this.query && !this.lookRef) {
        if (t.refObjId !== this.ref) {
          this.show(t.refObjId, lootMobCtx(t));
          return this.refresh();
        }
        // Same monster type, another individual (grade, level): refresh the header.
        this.ctx = lootMobCtx(t);
        this.sig = '';
      }
    }
    this.refresh();
  },

  mobName(ref) {
    const r = DropDB.mobs.get(ref);
    if (r && r.name) return r.name;
    if (this.ctx?.name && ref === this.ref) return this.ctx.name;
    for (const e of World.ents.values()) if (e.kind === 'monster' && e.refObjId === ref && e.name) return e.name;
    if (this.nameCache.has(ref)) return this.nameCache.get(ref) || '#' + ref;
    // Static name: model list codename -> SN_<codename> (loaded once, in the asset worker).
    this.nameCache.set(ref, '');
    Assets.npcModels()
      .then((rows) => {
        const row = (Array.isArray(rows) ? rows : []).find((x) => Array.isArray(x) && x[0] === ref);
        const name = row ? Items.text('SN_' + row[1], '') : '';
        if (name) {
          this.nameCache.set(ref, name);
          this.sig = '';
        }
      })
      .catch(() => {});
    return '#' + ref;
  },

  refresh() {
    if (!this.win || !this.win.isOpen()) return;
    this.renderStore();
    const searching = !!(this.lookRef || this.query.trim().length >= 2);
    const monster = !searching && !!this.ref;
    // The monster view redraws only when its own record changes, the list and search views
    // (built from every record) at most every 2 s while kills keep coming; data-only redraws
    // also wait while the pointer is over the list. A cleared sig always redraws.
    const view = [DropDB.bulk, DropDB.mode, this.ref, this.cls, this.query, this.lookRef, uiLang(), lootMyLevel(), Items.isLoaded() ? 1 : 0].join('|');
    const sig = view + '|' + (monster ? DropDB.revOf.get(this.ref) || 0 : DropDB.rev);
    if (sig === this.sig) return;
    if (this.sig && view === this.viewSig && (this.hovering || (!monster && now() - this.drawnAt < 2000))) return;
    this.sig = sig;
    this.viewSig = view;
    this.drawnAt = now();
    this.hoverText = null;
    this.renderHead();
    if (this.lookRef || this.query.trim().length >= 2) this.renderSearch();
    else if (this.ref) this.renderMonster();
    else this.renderList();
    this.updInfo();
  },

  renderHead() {
    const ref = this.ref;
    const searching = !!(this.lookRef || this.query.trim().length >= 2);
    this.backBtn.classList.toggle('hidden', !ref && !searching);
    this.backBtn.dataset.tip = searching ? (ref ? T('Canavara dön', 'Back to the monster') : T('Bilinen canavarlar', 'Known monsters')) : T('Bilinen canavarlar', 'Known monsters');
    if (!ref || searching) {
      this.iconEl.style.display = 'none';
      this.nameEl.textContent = this.lookRef
        ? lootItemName(this.lookRef, '#' + this.lookRef)
        : searching
          ? T('Arama', 'Search')
          : T('Bilinen canavarlar', 'Known monsters');
      this.nameEl.style.color = this.lookRef ? lootNameColor(this.lookRef, 0) : '#ffd65a';
      this.lvEl.textContent = '';
      this.clsEl.textContent = this.lookRef ? T('kim düşürür?', 'who drops it?') : '';
      this.win.setTitle(T('Drop envanteri', 'Drop inventory'));
      return;
    }
    const r = DropDB.mobs.get(ref);
    const ctx = this.ctx;
    const level = isNum(ctx?.level) ? ctx.level : r?.level;
    const cls = this.cls !== 'all' ? this.cls : ctx?.cls || this.mainClass(r);
    const name = this.mobName(ref);
    this.iconEl.style.display = '';
    Assets.bg(this.iconEl, lootRarityIcon(ctx && (ctx.cls === cls || this.cls === 'all') ? ctx : null, cls));
    this.nameEl.textContent = name;
    this.nameEl.style.color = lootLvColor(level);
    this.lvEl.textContent = isNum(level) && level > 0 ? 'Lv ' + level : '';
    // A live party monster reads like the game's target window: "<grade> (Party)".
    const live = !!ctx && (ctx.cls === cls || this.cls === 'all');
    this.clsEl.textContent = live && ctx.party ? lootClassLabel(RARITY[ctx.rarity ?? 0] || 'normal') + ' ' + T('(Parti)', '(Party)') : lootClassLabel(cls);
    this.win.setTitle(T('Drop envanteri', 'Drop inventory') + ' · ' + name);
  },

  mainClass(r) {
    if (!r) return 'normal';
    let best = 'normal';
    let n = -1;
    for (const [k, v] of Object.entries(r.kills)) if (v > n) [best, n] = [k, v];
    return best;
  },

  renderTabs(r) {
    this.tabsHost.textContent = '';
    if (!this.ref) return;
    const classes = DropDB.classesOf(r);
    if (this.ctx?.cls && !classes.includes(this.ctx.cls)) classes.push(this.ctx.cls);
    if (this.cls !== 'all' && !classes.includes(this.cls)) classes.push(this.cls);
    const items = [['all', T('Tümü', 'All')], ...LOOT_CLASSES.filter((k) => classes.includes(k)).map((k) => [k, lootClassLabel(k)])];
    const set = (k) => {
      this.cls = k;
      this.refresh();
    };
    let el;
    if (items.length <= 5) {
      el = tabBar(items, () => this.cls, set, true);
      el.classList.add('ld-tabs');
    } else {
      el = h('div', { class: 'lt-bar' }, h('span', { class: 'dim', text: T('Sınıf', 'Class') }), selectBox(items, () => this.cls, set));
    }
    this.tabsHost.append(el);
  },

  renderMonster() {
    const r = DropDB.mobs.get(this.ref);
    this.renderTabs(r);
    const s = DropDB.summary(this.ref, this.cls);
    const kills = s ? s.kills : 0;
    this.statEl.textContent = s
      ? T(`Öldürme ${fmtInt(kills)} · eşya ${fmtInt(s.drops)} · altın ${fmtInt(s.goldDrops)}`, `Kills ${fmtInt(kills)} · items ${fmtInt(s.drops)} · gold ${fmtInt(s.goldDrops)}`)
      : T('Henüz gözlem yok', 'No observations yet');
    this.statEl.dataset.tip = s
      ? Object.entries(s.killsByClass)
          .map(([k, v]) => `${lootClassLabel(k)}: ${fmtInt(v)}`)
          .join('\n') + (s.first ? '\n' + T('İlk kayıt: ', 'First seen: ') + new Date(s.first).toLocaleString() : '')
      : '';
    this.setGold(s?.gold, s?.goldRate);
    this.scroll.textContent = '';
    if (!s || !s.items.length) {
      this.scroll.append(
        h('div', {
          class: 'empty',
          text: T('Bu canavar için henüz eşya düşüşü görülmedi. Yakınınızda (60 m) öldükçe düşenler buraya eklenir.', 'No item drops seen for this monster yet. Drops of kills near you (60 m) are added here.'),
        })
      );
      return;
    }
    const grid = h('div', { class: 'ld-grid' });
    for (const it of s.items) grid.append(this.itemCell(it, kills));
    this.scroll.append(grid);
  },

  itemCell(it, kills) {
    const tf = it.tf >>> 0;
    const slot = itemSlot({ refObjId: it.ref, typeFlags: tf, groundItem: { typeFlags: tf } }, { size: 36, showQty: false, tip: () => lootSafe(() => this.itemTip(it, kills), 'drop-tip') || '' });
    slot.addEventListener('click', () => this.lookupItem(it.ref));
    const label = h('b', null, h('em', { text: fmtInt(it.n) }), kills ? '/' + fmtInt(kills) : '');
    const cell = h('div', { class: 'ld-cell' }, slot, label);
    const nameColor = lootNameColor(it.ref, 0);
    const line2 = () => {
      const bits = [`${fmtInt(it.n)} / ${fmtInt(kills)} ${T('öldürme', 'kills')} · ${lootPct(it.rate)}`];
      if (it.qtyMax > 1) bits.push(T(`adet ${it.qtyMin}–${it.qtyMax}`, `qty ${it.qtyMin}–${it.qtyMax}`));
      bits.push(T('son: ', 'last: ') + lootAgo(it.lastAt));
      return bits.join(' · ');
    };
    cell.addEventListener('pointerenter', () => {
      this.hoverText = [it.name, nameColor, line2()];
      this.updInfo();
    });
    cell.addEventListener('pointerleave', () => {
      this.hoverText = null;
      this.updInfo();
    });
    return cell;
  },

  itemTip(it, kills) {
    return lootDropTip(this.ref, it, kills, this.cls);
  },

  setGold(gold, rate) {
    const on = !!gold;
    this.coinEl.style.visibility = on ? '' : 'hidden';
    this.goldEl.textContent = on ? `${Items.goldText(gold.min)} – ${Items.goldText(gold.max)}` : '';
    this.goldEl.style.color = on ? Items.goldColor(gold.max) : '';
    this.goldEl.dataset.tip = on
      ? T(`Altın: ${fmtInt(gold.n)} kez (${lootPct(rate)}), ortalama ${Items.goldText(gold.avg)}`, `Gold: ${fmtInt(gold.n)} times (${lootPct(rate)}), average ${Items.goldText(gold.avg)}`)
      : '';
  },

  mobRow(r, extra) {
    const name = r.name || this.mobName(r.ref);
    const kills = DropDB.totalKills(r);
    const row = h(
      'div',
      { class: 'li', onclick: () => this.open(r.ref) },
      h('span', { class: 'grow ellip', style: { color: lootLvColor(r.level) }, text: name }),
      r.level ? h('span', { class: 'lv', text: 'Lv ' + r.level }) : null,
      h('span', { class: 'ct', text: extra ?? T(`${fmtInt(kills)} öldürme · ${Object.keys(r.items).length} eşya`, `${fmtInt(kills)} kills · ${Object.keys(r.items).length} items`) })
    );
    return row;
  },

  renderList() {
    this.tabsHost.textContent = '';
    const mobs = [...DropDB.mobs.values()].sort((a, b) => (b.last || 0) - (a.last || 0));
    let kills = 0;
    for (const r of mobs) kills += DropDB.totalKills(r);
    this.statEl.textContent = T(`${fmtInt(mobs.length)} canavar · ${fmtInt(kills)} öldürme`, `${fmtInt(mobs.length)} monsters · ${fmtInt(kills)} kills`);
    this.statEl.dataset.tip = '';
    this.setGold(null);
    this.scroll.textContent = '';
    if (!mobs.length) {
      this.scroll.append(
        h('div', {
          class: 'empty',
          text:
            DropDB.mode === 'loading'
              ? T('Kayıtlar yükleniyor…', 'Loading records…')
              : T('Henüz kayıt yok. Canavar avladıkça düşenler burada birikir; bir canavarı seçip hedef çubuğundaki oka da basabilirsiniz.', 'No records yet. Drops build up here as you hunt; you can also select a monster and press the arrow in its target bar.'),
        })
      );
      return;
    }
    const list = h('div', { class: 'list ld-list' });
    for (const r of mobs.slice(0, 300)) list.append(this.mobRow(r));
    this.scroll.append(list);
  },

  renderSearch() {
    this.tabsHost.textContent = '';
    this.setGold(null);
    this.scroll.textContent = '';
    const q = this.query.trim().toLowerCase();
    const list = h('div', { class: 'list ld-list' });
    let mobsShown = 0;
    if (!this.lookRef) {
      const mobs = [...DropDB.mobs.values()].filter((r) => (r.name || '').toLowerCase().includes(q)).slice(0, 30);
      if (mobs.length) {
        list.append(h('div', { class: 'ld-sec' }, h('span', { text: T('Canavarlar', 'Monsters') })));
        for (const r of mobs) list.append(this.mobRow(r));
        mobsShown = mobs.length;
      }
    }
    // Items: the looked-up reference, or every observed item whose name matches.
    const refs = new Map();
    if (this.lookRef) refs.set(this.lookRef, lootItemName(this.lookRef, ''));
    else {
      for (const r of DropDB.mobs.values()) {
        for (const [k, it] of Object.entries(r.items)) {
          const ref = Number(k);
          if (refs.has(ref)) continue;
          const name = lootItemName(ref, it.name);
          if (name.toLowerCase().includes(q)) refs.set(ref, name);
          if (refs.size >= 40) break;
        }
        if (refs.size >= 40) break;
      }
    }
    let itemsShown = 0;
    for (const [ref, name] of refs) {
      const droppers = DropDB.droppersOf(ref);
      const tf = this.tfOf(ref);
      const slot = itemSlot({ refObjId: ref, typeFlags: tf, groundItem: { typeFlags: tf } }, { size: 24, showQty: false });
      list.append(h('div', { class: 'ld-sec' }, slot, h('span', { style: { color: lootNameColor(ref, 0) }, text: name || '#' + ref })));
      itemsShown++;
      if (!droppers.length) {
        list.append(h('div', { class: 'empty', text: T('Bu eşyayı düşüren bir canavar henüz görülmedi.', 'No monster has been seen dropping this item yet.') }));
        continue;
      }
      for (const d of droppers.slice(0, 20)) {
        const r = DropDB.mobs.get(d.mobRef);
        if (r) list.append(this.mobRow(r, `${fmtInt(d.n)}/${fmtInt(d.kills)} · ${lootPct(d.rate)}`));
      }
    }
    this.statEl.textContent = this.lookRef
      ? T('Bu eşyayı düşüren canavarlar', 'Monsters that drop this item')
      : T(`Arama: ${mobsShown} canavar, ${itemsShown} eşya`, `Search: ${mobsShown} monsters, ${itemsShown} items`);
    this.statEl.dataset.tip = '';
    if (!mobsShown && !itemsShown) list.append(h('div', { class: 'empty', text: T('Eşleşen kayıt yok.', 'No matching record.') }));
    this.scroll.append(list);
  },

  tfOf(ref) {
    for (const r of DropDB.mobs.values()) {
      const it = r.items[ref];
      if (it && it.tf) return it.tf >>> 0;
    }
    return 0;
  },

  updInfo() {
    if (!this.i1) return;
    if (this.hoverText) {
      const [a, color, b] = this.hoverText;
      this.i1.textContent = a;
      this.i1.style.color = color || '';
      this.i2.textContent = b;
      return;
    }
    this.i1.style.color = '';
    if (this.ref && !this.query && !this.lookRef) {
      const s = DropDB.summary(this.ref, this.cls);
      this.i1.textContent = s && s.items.length ? T(`${s.items.length} farklı eşya gözlendi`, `${s.items.length} different items observed`) : T('Gözlem bekleniyor', 'Waiting for observations');
      this.i2.textContent = s && s.last ? T('Son kayıt: ', 'Last record: ') + lootAgo(s.last) + T(' · oranlar yaklaşıktır', ' · rates are approximate') : T('Oran = düşüş / yakında görülen öldürme', 'Rate = drops / kills seen nearby');
    } else {
      this.i1.textContent = T('Bir eşyaya tıklayın: onu düşüren tüm canavarlar listelenir.', 'Click an item to list every monster that drops it.');
      this.i2.textContent = T('Kayıtlar yalnız bu tarayıcıda tutulur; dışa aktarıp paylaşabilirsiniz.', 'Records stay in this browser; export them to share.');
    }
  },

  renderStore() {
    const where = DropDB.mode === 'idb' ? T('tarayıcıda kalıcı', 'stored in the browser') : DropDB.mode === 'loading' ? T('yükleniyor…', 'loading…') : T('yalnız bellekte (kalıcı değil)', 'memory only (not persistent)');
    const text = T(`${DropDB.mobs.size} canavar · ${where}`, `${DropDB.mobs.size} monsters · ${where}`);
    if (this.storeEl.textContent !== text) this.storeEl.textContent = text;
  },

  confirmClear() {
    const btn = this.clearBtn;
    if (btn.dataset.armed === '1') {
      btn.dataset.armed = '';
      btn.textContent = T('Temizle', 'Clear');
      DropDB.clear();
      UI.toast(T('Drop kayıtları silindi', 'Drop records deleted'), 'info', 2500);
      this.sig = '';
      this.refresh();
      return;
    }
    btn.dataset.armed = '1';
    btn.textContent = T('Emin misiniz?', 'Sure?');
    setTimeout(() => {
      if (btn.dataset.armed === '1') {
        btn.dataset.armed = '';
        btn.textContent = T('Temizle', 'Clear');
      }
    }, 3000);
  },

  exportFile() {
    try {
      DropDB.flush();
      const blob = new Blob([DropDB.exportJson()], { type: 'application/json' });
      const url = URL.createObjectURL(blob);
      const d = new Date();
      const stamp = `${d.getFullYear()}${String(d.getMonth() + 1).padStart(2, '0')}${String(d.getDate()).padStart(2, '0')}`;
      const a = h('a', { href: url, download: `sro-drop-kayitlari-${stamp}.json`, style: { display: 'none' } });
      UI.layer.append(a);
      a.click();
      a.remove();
      setTimeout(() => URL.revokeObjectURL(url), 5000);
    } catch (e) {
      UI.toast(T('Dışa aktarılamadı: ', 'Export failed: ') + (e && e.message ? e.message : e), 'warn', 3000);
    }
  },

  importFile() {
    const input = h('input', { type: 'file', accept: '.json,application/json', style: { display: 'none' } });
    input.addEventListener('change', () => {
      const f = input.files && input.files[0];
      input.remove();
      if (!f) return;
      if (f.size > 20 * 1024 * 1024) {
        UI.toast(T('Dosya çok büyük', 'File too large'), 'warn', 3000);
        return;
      }
      // The store must be loaded first: it holds the earlier snapshot of the same source.
      Promise.all([f.text(), DropDB.ready()])
        .then(([text]) => {
          const n = DropDB.importJson(text);
          UI.toast(T(`${n} canavar kaydı içe aktarıldı`, `${n} monster records imported`), 'info', 3000);
          this.sig = '';
          this.refresh();
        })
        .catch((e) => UI.toast(T('İçe aktarılamadı: ', 'Import failed: ') + (e && e.message ? e.message : e), 'warn', 3500));
    });
    UI.layer.append(input);
    input.click();
  },
};

// ---- Arrow inside the game's monster target bar (R8 targetbar) ----------------------------------
// clear-target is at [x+W-20, 7+9, 16, 16] of the 196x78 monster window; the arrow takes the
// bottom-right corner below it: [176, 58, 16, 16] -> left = cr.left, top = cr.top + 49 s.

const LootTargetBtn = {
  el: null,

  init() {
    if (this.el) return;
    const base = LOOT_IMG + 'interface/ifcommon/com_right_arrow';
    const layers = ['n', 'f', 'p'].map((k) => h('i', { class: k }));
    Assets.bg(layers[0], base + '.png');
    Assets.bg(layers[1], base + '_focus.png');
    Assets.bg(layers[2], base + '_press.png');
    this.el = h(
      'div',
      {
        class: 'lt-tbtn hidden',
        onclick: () =>
          lootSafe(() => {
            const t = World.target();
            if (t && t.kind === 'monster') MobDrops.open(t.refObjId, lootMobCtx(t));
          }, 'target-btn'),
      },
      layers
    );
    // Built when the tooltip shows, not on every placement.
    this.el._tip = () =>
      lootSafe(() => {
        const t = World.target();
        const r = t && t.kind === 'monster' ? DropDB.mobs.get(t.refObjId) : null;
        const hk = Settings.global.hotkeys.drops;
        const kills = r ? fmtInt(DropDB.totalKills(r)) : '';
        const items = r ? Object.keys(r.items).length : 0;
        return T('Drop envanteri (gözlenen)', 'Drop inventory (observed)') + (hk ? ` (${hk})` : '') + (r ? T(`\n${kills} öldürme · ${items} eşya`, `\n${kills} kills · ${items} items`) : '');
      }, 'target-tip') || '';
    UI.layer.append(this.el);
    setInterval(() => {
      try {
        this.place();
      } catch {
        this.hide();
      }
    }, 300);
  },

  hide() {
    this.el?.classList.add('hidden');
  },

  place() {
    const t = World.target();
    if (!lootCfg().targetButton || World.phase !== 'world' || !t || t.kind !== 'monster') return this.hide();
    const anchor = document.querySelector('[data-gpu-ui="semantics"] [data-ui-id="clear-target"]');
    if (!anchor) return this.hide();
    const cr = anchor.getBoundingClientRect();
    if (!cr.width) return this.hide();
    const s = cr.width / 16;
    const size = Math.max(10, Math.round(16 * s));
    Object.assign(this.el.style, { left: Math.round(cr.left) + 'px', top: Math.round(cr.top + 49 * s) + 'px', width: size + 'px', height: size + 'px' });
    this.el.classList.remove('hidden');
  },
};

// ---- Public API for other modules ----------------------------------------------------------------

const MobDrops = {
  db: DropDB,
  // ctx (optional): { name, level, rarity, party, cls } of a live monster.
  open(refObjId, ctx) {
    lootSafe(() => LootDropWin.open(refObjId, ctx), 'mobdrops-open');
  },
  // -> Node: compact observed-drops card (kills, top items, gold range, "Drop inventory" button);
  //    node.data holds the numbers of stats() (null when nothing was observed).
  summary(refObjId, cls) {
    return lootSafe(() => lootSummaryNode(Number(refObjId), cls || 'all'), 'mobdrops-summary') || null;
  },
  // -> { ref, name, level, cls, kills, killsByClass, drops, goldDrops, gold {n,min,max,sum,avg} | null,
  //      goldRate, items [{ref, n, rate, name, tf, qtyMin, qtyMax, firstAt, lastAt, byClass}], first, last } | null
  stats(refObjId, cls) {
    return lootSafe(() => DropDB.summary(Number(refObjId), cls || 'all'), 'mobdrops-stats') || null;
  },
  // -> [{ mobRef, name, level, n, kills, rate }] best rate first
  droppersOf(itemRef) {
    return lootSafe(() => DropDB.droppersOf(Number(itemRef)), 'mobdrops-droppers') || [];
  },
  lookupItem(itemRef) {
    lootSafe(() => LootDropWin.lookupItem(itemRef), 'mobdrops-lookup');
  },
  toggle() {
    LootDropWin.toggle();
  },
};

const Loot = {
  inited: false,
  init() {
    if (this.inited) return;
    this.inited = true;
    try {
      UI.root.append(h('style', null, LOOT_CSS));
    } catch {}
    try {
      ItemSlot.css();
    } catch {}
    Items.ready();
    DropDB.ready();
    LootTrack.init();
    LootPick.init();
    LootWin.init();
    LootDropWin.init();
    LootTargetBtn.init();
    // Best-effort write of pending records when the tab goes away.
    W.addEventListener('pagehide', () => lootSafe(() => DropDB.flush(), 'flush'));
    document.addEventListener('visibilitychange', () => {
      if (document.visibilityState === 'hidden') lootSafe(() => DropDB.flush(), 'flush');
    });
  },
};

